FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n  chronoSessions ChronoSession[]\n  circuitLogs    CampCircuitLog[]\n  restDays       RestDay[]\n  favoriteCircuits FavoriteCircuit[]\n  reactions      Reaction[]\n  resetTokens    PasswordResetToken[]\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  circuits  CampCircuit[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  circuitLogs CampCircuitLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n\n// Seance de circuit training "libre" (construite depuis l\'onglet Chrono, pas liee a un camp).\n// Enregistree une fois terminee, pour alimenter l\'historique d\'activite de l\'utilisateur.\nmodel ChronoSession {\n  id                   String   @id @default(cuid())\n  userId               String\n  name                 String? // nom optionnel donne par l\'utilisateur\n  items                String  // JSON : liste ordonnee des noms d\'exercices du circuit\n  workSeconds          Int\n  restSeconds          Int\n  rounds               Int\n  roundRestSeconds     Int\n  totalDurationSeconds Int\n  completedAt          DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Circuit training defini par le createur d\'un camp (alternative aux exercices individuels).\n// Compose d\'une liste ordonnee d\'exercices avec temps de travail/repos, nombre de tours, etc.\nmodel CampCircuit {\n  id               String   @id @default(cuid())\n  campId           String\n  name             String\n  description      String?\n  items            String   // JSON : [{ "exerciseId": "...", "name": "..." }, ...] ordonne\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  recurrenceType   String   @default("DAILY")\n  daysOfWeek       String?\n  intervalDays     Int?\n  startDate        DateTime @default(now())\n\n  camp Camp             @relation(fields: [campId], references: [id], onDelete: Cascade)\n  logs CampCircuitLog[]\n}\n\n// Validation, par un membre, d\'un circuit de camp realise un jour donne\nmodel CampCircuitLog {\n  id              String   @id @default(cuid())\n  userId          String\n  campCircuitId   String\n  campId          String\n  date            DateTime\n  durationSeconds Int\n  completed       Boolean  @default(true)\n  createdAt       DateTime @default(now())\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  campCircuit CampCircuit @relation(fields: [campCircuitId], references: [id], onDelete: Cascade)\n  camp        Camp        @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campCircuitId, date])\n}\n\n// Jour marque comme "repos justifie" par l\'utilisateur (blessure, voyage...) : ce jour\n// n\'est jamais compte comme un manque dans les calculs de regularite/streak, ni comme du\n// depend  (il est neutre). S\'applique globalement, tous camps/exercices confondus.\nmodel RestDay {\n  id        String   @id @default(cuid())\n  userId    String\n  date      DateTime // jour concerne (heure normalisee a minuit)\n  reason    String?\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date])\n}\n\n// Circuit training "favori" enregistre par un utilisateur depuis l\'onglet Chrono,\n// pour le relancer directement sans le reconstruire.\nmodel FavoriteCircuit {\n  id               String   @id @default(cuid())\n  userId           String\n  name             String\n  items            String   // JSON : liste ordonnee des noms d\'exercices\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  createdAt        DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Reaction rapide (encouragement) laissee par un membre de camp sur une seance validee\n// par un autre membre (exercice ou circuit). Purement social, aucun impact sur les stats.\nmodel Reaction {\n  id         String   @id @default(cuid())\n  userId     String   // qui reagit\n  targetType String   // "exercise" ou "circuit" (type de log cible)\n  targetId   String   // id du ExerciseLog ou CampCircuitLog cible\n  type       String   // cle du type de reaction, voir src/utils/reactions.ts\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, targetType, targetId, type])\n}\n\n// Jeton de reinitialisation de mot de passe, a duree de vie limitee\nmodel PasswordResetToken {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n'
FILES['backend/src/index.ts'] = 'import "dotenv/config";\nimport express from "express";\nimport cors from "cors";\n\nimport authRoutes from "./routes/auth";\nimport userRoutes from "./routes/users";\nimport exerciseRoutes from "./routes/exercises";\nimport campRoutes from "./routes/camps";\nimport campExerciseRoutes from "./routes/campExercises";\nimport todayRoutes from "./routes/today";\nimport logRoutes from "./routes/logs";\nimport progressRoutes from "./routes/progress";\nimport pushRoutes from "./routes/push";\nimport badgeRoutes from "./routes/badges";\nimport campMessageRoutes from "./routes/campMessages";\nimport messageRoutes from "./routes/messages";\nimport campCircuitRoutes from "./routes/campCircuits";\nimport chronoSessionRoutes from "./routes/chronoSessions";\nimport activityRoutes from "./routes/activity";\nimport restDayRoutes from "./routes/restDays";\nimport reactionRoutes from "./routes/reactions";\nimport favoriteCircuitRoutes from "./routes/favoriteCircuits";\nimport { initPush, scheduleReminders } from "./services/notifications";\n\nconst app = express();\n\napp.use(cors({ origin: process.env.FRONTEND_URL || "*" }));\napp.use(express.json());\n\napp.get("/api/health", (_req, res) => res.json({ status: "ok" }));\n\napp.use("/api/auth", authRoutes);\napp.use("/api/users", userRoutes);\napp.use("/api/exercises", exerciseRoutes);\napp.use("/api/camps", campRoutes);\napp.use("/api/camp-exercises", campExerciseRoutes);\napp.use("/api/today", todayRoutes);\napp.use("/api/logs", logRoutes);\napp.use("/api/progress", progressRoutes);\napp.use("/api/push", pushRoutes);\napp.use("/api/badges", badgeRoutes);\napp.use("/api/camps", campMessageRoutes);\napp.use("/api/messages", messageRoutes);\napp.use("/api/camp-circuits", campCircuitRoutes);\napp.use("/api/chrono-sessions", chronoSessionRoutes);\napp.use("/api/activity", activityRoutes);\napp.use("/api/rest-days", restDayRoutes);\napp.use("/api/reactions", reactionRoutes);\napp.use("/api/favorite-circuits", favoriteCircuitRoutes);\n\n// Gestion d\'erreur generique (evite qu\'une exception fasse planter le process)\napp.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {\n  console.error(err);\n  res.status(500).json({ error: "Erreur interne du serveur." });\n});\n\nconst port = Number(process.env.PORT || 4000);\n\ninitPush();\nscheduleReminders();\n\napp.listen(port, () => {\n  console.log(`API demarree sur http://localhost:${port}`);\n});\n'
FILES['backend/src/routes/auth.ts'] = 'import { Router } from "express";\nimport bcrypt from "bcryptjs";\nimport jwt from "jsonwebtoken";\nimport crypto from "crypto";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { sendEmail } from "../services/email";\n\nconst router = Router();\n\nconst registerSchema = z.object({\n  email: z.string().email("Adresse email invalide."),\n  password: z.string().min(8, "Le mot de passe doit faire au moins 8 caracteres."),\n  name: z.string().min(1, "Le nom est requis."),\n});\n\nconst loginSchema = z.object({\n  email: z.string().email(),\n  password: z.string().min(1),\n});\n\nfunction signToken(userId: string): string {\n  const secret = process.env.JWT_SECRET as string;\n  const expiresIn = process.env.JWT_EXPIRES_IN || "30d";\n  return jwt.sign({ userId }, secret, { expiresIn } as jwt.SignOptions);\n}\n\nfunction toPublicUser(user: {\n  id: string;\n  email: string;\n  name: string;\n  weightKg: number | null;\n  heightCm: number | null;\n  birthDate: Date | null;\n  sex: string | null;\n}) {\n  return {\n    id: user.id,\n    email: user.email,\n    name: user.name,\n    weightKg: user.weightKg,\n    heightCm: user.heightCm,\n    birthDate: user.birthDate,\n    sex: user.sex,\n  };\n}\n\nrouter.post("/register", async (req, res) => {\n  const parsed = registerSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { email, password, name } = parsed.data;\n\n  const existing = await prisma.user.findUnique({ where: { email } });\n  if (existing) {\n    return res.status(409).json({ error: "Un compte existe deja avec cet email." });\n  }\n\n  const passwordHash = await bcrypt.hash(password, 10);\n  const user = await prisma.user.create({ data: { email, passwordHash, name } });\n\n  const token = signToken(user.id);\n  return res.status(201).json({ token, user: toPublicUser(user) });\n});\n\nrouter.post("/login", async (req, res) => {\n  const parsed = loginSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Email et mot de passe requis." });\n  }\n  const { email, password } = parsed.data;\n\n  const user = await prisma.user.findUnique({ where: { email } });\n  if (!user) {\n    return res.status(401).json({ error: "Email ou mot de passe incorrect." });\n  }\n\n  const valid = await bcrypt.compare(password, user.passwordHash);\n  if (!valid) {\n    return res.status(401).json({ error: "Email ou mot de passe incorrect." });\n  }\n\n  const token = signToken(user.id);\n  return res.json({ token, user: toPublicUser(user) });\n});\n\nconst forgotSchema = z.object({ email: z.string().email() });\n\n// Demande de reinitialisation : genere un jeton valable 1h et envoie un email (si configure).\n// Repond toujours de la meme facon, que l\'email existe ou non, pour ne pas reveler qui a un compte.\nrouter.post("/forgot-password", async (req, res) => {\n  const parsed = forgotSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Adresse email invalide." });\n  }\n  const { email } = parsed.data;\n\n  const genericResponse = {\n    message: "Si un compte existe avec cet email, un lien de reinitialisation vient d\'etre envoye.",\n  };\n\n  const user = await prisma.user.findUnique({ where: { email } });\n  if (!user) return res.json(genericResponse);\n\n  const token = crypto.randomBytes(32).toString("hex");\n  const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 heure\n\n  await prisma.passwordResetToken.create({ data: { userId: user.id, token, expiresAt } });\n\n  const frontendUrl = process.env.FRONTEND_URL || "http://localhost:5173";\n  const resetLink = `${frontendUrl}/reinitialiser-mot-de-passe?token=${token}`;\n\n  await sendEmail(\n    email,\n    "Reinitialisation de ton mot de passe GoTeam",\n    `Bonjour ${user.name},\\n\\nClique sur ce lien pour choisir un nouveau mot de passe (valable 1 heure) :\\n${resetLink}\\n\\nSi tu n\'es pas a l\'origine de cette demande, ignore simplement cet email.`\n  );\n\n  return res.json(genericResponse);\n});\n\nconst resetSchema = z.object({\n  token: z.string().min(1),\n  newPassword: z.string().min(8, "Le mot de passe doit faire au moins 8 caracteres."),\n});\n\n// Applique le nouveau mot de passe si le jeton est valide, non expire et non deja utilise\nrouter.post("/reset-password", async (req, res) => {\n  const parsed = resetSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { token, newPassword } = parsed.data;\n\n  const resetToken = await prisma.passwordResetToken.findUnique({ where: { token } });\n  if (!resetToken || resetToken.used || resetToken.expiresAt.getTime() < Date.now()) {\n    return res.status(400).json({ error: "Ce lien de reinitialisation est invalide ou a expire." });\n  }\n\n  const passwordHash = await bcrypt.hash(newPassword, 10);\n  await prisma.$transaction([\n    prisma.user.update({ where: { id: resetToken.userId }, data: { passwordHash } }),\n    prisma.passwordResetToken.update({ where: { id: resetToken.id }, data: { used: true } }),\n  ]);\n\n  res.json({ message: "Mot de passe mis a jour, tu peux te connecter." });\n});\n\nexport default router;\n'
FILES['backend/src/routes/camps.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { generateCampCode } from "../utils/code";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst createCampSchema = z.object({\n  name: z.string().min(1, "Le nom du camp est requis."),\n  description: z.string().max(500).optional().nullable(),\n  exerciseIds: z.array(z.string()).min(1, "Selectionne au moins un exercice."),\n  startDate: z.string().optional().nullable(), // format ISO "YYYY-MM-DD"\n  endDate: z.string().optional().nullable(),\n});\n\n// Cree un camp : choix d\'un ensemble d\'exercices, generation d\'un code d\'invitation.\n// Le createur devient automatiquement membre du camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { name, description, exerciseIds, startDate, endDate } = parsed.data;\n\n  if (startDate && endDate && new Date(endDate) < new Date(startDate)) {\n    return res.status(400).json({ error: "La date de fin doit etre apres la date de debut." });\n  }\n\n  // On genere un code unique (tres faible probabilite de collision, on retente si besoin)\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const camp = await prisma.camp.create({\n    data: {\n      name,\n      description: description || null,\n      code,\n      createdById: req.userId!,\n      startDate: startDate ? new Date(startDate) : null,\n      endDate: endDate ? new Date(endDate) : null,\n      exercises: { create: exerciseIds.map((exerciseId) => ({ exerciseId })) },\n      members: { create: [{ userId: req.userId! }] },\n    },\n    include: { exercises: { include: { exercise: true } }, members: true },\n  });\n\n  res.status(201).json(camp);\n});\n\nconst joinSchema = z.object({ code: z.string().min(1) });\n\n// Rejoint un camp existant via son code d\'invitation\nrouter.post("/join", async (req: AuthRequest, res) => {\n  const parsed = joinSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Code requis." });\n  }\n  const code = parsed.data.code.trim().toUpperCase();\n\n  const camp = await prisma.camp.findUnique({ where: { code } });\n  if (!camp) {\n    return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n  }\n\n  const existing = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: camp.id } },\n  });\n  if (existing) {\n    return res.status(200).json({ message: "Tu es deja membre de ce camp.", campId: camp.id });\n  }\n\n  await prisma.campMembership.create({ data: { userId: req.userId!, campId: camp.id } });\n  res.status(201).json({ message: `Bienvenue dans le camp "${camp.name}" !`, campId: camp.id });\n});\n\n// Liste les camps dont l\'utilisateur est membre\nrouter.get("/mine", async (req: AuthRequest, res) => {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: {\n          exercises: { include: { exercise: true } },\n          _count: { select: { members: true } },\n        },\n      },\n    },\n    orderBy: { joinedAt: "desc" },\n  });\n  res.json(memberships.map((m) => m.camp));\n});\n\n// Detail d\'un camp (verifie que l\'utilisateur en est bien membre)\nrouter.get("/:id", async (req: AuthRequest, res) => {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: req.params.id } },\n  });\n  if (!membership) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: {\n      exercises: { include: { exercise: true } },\n      circuits: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  res.json(camp);\n});\n\nconst updateCampSchema = z.object({\n  name: z.string().min(1).optional(),\n  description: z.string().max(500).optional().nullable(),\n});\n\n// Modifie le nom/descriptif d\'un camp : reserve au createur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le modifier." });\n  }\n\n  const parsed = updateCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n\n  const updated = await prisma.camp.update({\n    where: { id: req.params.id },\n    data: parsed.data,\n  });\n  res.json(updated);\n});\n\n// Supprime definitivement un camp : reserve au createur du camp.\n// Supprime aussi en cascade les exercices du camp, les adhesions, les logs et les messages associes.\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le supprimer." });\n  }\n\n  await prisma.camp.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\n// Classement des membres du camp base UNIQUEMENT sur leur regularite personnelle\n// (taux de seances realisees par rapport aux seances dues, et jours consecutifs) --\n// jamais sur les performances (poids, repetitions, etc.).\nrouter.get("/:id/leaderboard", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: campId },\n    include: {\n      exercises: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const today = toDayStart(new Date());\n  const results = [];\n\n  for (const member of camp.members) {\n    const logs = await prisma.exerciseLog.findMany({\n      where: { userId: member.userId, campId },\n      select: { date: true },\n    });\n    const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n    const restDays = await prisma.restDay.findMany({ where: { userId: member.userId }, select: { date: true } });\n    const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n\n    let dueCount = 0;\n    let doneCount = 0;\n    for (const ce of camp.exercises) {\n      const effectiveStart = toDayStart(\n        new Date(Math.max(new Date(ce.startDate).getTime(), new Date(member.joinedAt).getTime()))\n      );\n      const cursor = new Date(effectiveStart);\n      while (cursor.getTime() <= today.getTime()) {\n        const key = cursor.toISOString().slice(0, 10);\n        if (!restDates.has(key) && isDueOnDate(ce, cursor)) {\n          dueCount++;\n          if (completedDates.has(key)) doneCount++;\n        }\n        cursor.setUTCDate(cursor.getUTCDate() + 1);\n      }\n    }\n    const regularityRate = dueCount > 0 ? Math.round((doneCount / dueCount) * 100) : 0;\n\n    // Streak propre a ce camp : jours consecutifs (en remontant depuis aujourd\'hui/hier)\n    // avec au moins une seance validee dans ce camp. Les jours de repos justifie sont neutres.\n    let streak = 0;\n    const cursor2 = toDayStart(today);\n    if (!completedDates.has(cursor2.toISOString().slice(0, 10)) && !restDates.has(cursor2.toISOString().slice(0, 10))) {\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n    for (let i = 0; i < 3650; i++) {\n      const key = cursor2.toISOString().slice(0, 10);\n      if (restDates.has(key)) {\n        cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n        continue;\n      }\n      if (!completedDates.has(key)) break;\n      streak++;\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n\n    results.push({\n      userId: member.userId,\n      name: member.user.name,\n      regularityRate,\n      streak,\n      dueCount,\n      doneCount,\n    });\n  }\n\n  results.sort((a, b) => b.regularityRate - a.regularityRate || b.streak - a.streak);\n  res.json(results);\n});\n\n// Duplique un camp (nom, descriptif, exercices et circuits avec leurs consignes) pour\n// relancer une nouvelle "saison" sans tout reconfigurer. Reserve au createur du camp.\n// Les membres, l\'historique et les messages ne sont PAS copies.\nrouter.post("/:id/duplicate", async (req: AuthRequest, res) => {\n  const original = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: { exercises: true, circuits: true },\n  });\n  if (!original) return res.status(404).json({ error: "Camp introuvable." });\n  if (original.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur du camp peut le dupliquer." });\n  }\n\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const duplicate = await prisma.camp.create({\n    data: {\n      name: `${original.name} (copie)`,\n      description: original.description,\n      code,\n      createdById: req.userId!,\n      exercises: {\n        create: original.exercises.map((ce) => ({\n          exerciseId: ce.exerciseId,\n          description: ce.description,\n          targetSets: ce.targetSets,\n          targetMode: ce.targetMode,\n          targetValue: ce.targetValue,\n          recurrenceType: ce.recurrenceType,\n          daysOfWeek: ce.daysOfWeek,\n          intervalDays: ce.intervalDays,\n        })),\n      },\n      circuits: {\n        create: original.circuits.map((c) => ({\n          name: c.name,\n          description: c.description,\n          items: c.items,\n          workSeconds: c.workSeconds,\n          restSeconds: c.restSeconds,\n          rounds: c.rounds,\n          roundRestSeconds: c.roundRestSeconds,\n          recurrenceType: c.recurrenceType,\n          daysOfWeek: c.daysOfWeek,\n          intervalDays: c.intervalDays,\n        })),\n      },\n      members: { create: [{ userId: req.userId! }] },\n    },\n  });\n\n  res.status(201).json(duplicate);\n});\n\n// Vue calendrier d\'un mois pour l\'utilisateur courant : pour chaque jour, etait-ce du\n// (au moins un exercice/circuit du camp) et a-t-il ete fait (au moins un valide) ?\nrouter.get("/:id/calendar", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const monthParam = (req.query.month as string) || new Date().toISOString().slice(0, 7); // "YYYY-MM"\n  const [yearStr, monthStr] = monthParam.split("-");\n  const year = Number(yearStr);\n  const month = Number(monthStr); // 1-12\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: campId },\n    include: { exercises: true, circuits: true },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const [logs, circuitLogs, restDays] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId: req.userId, campId }, select: { date: true } }),\n    prisma.campCircuitLog.findMany({ where: { userId: req.userId, campId }, select: { date: true } }),\n    prisma.restDay.findMany({ where: { userId: req.userId }, select: { date: true } }),\n  ]);\n  const doneDates = new Set([\n    ...logs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...circuitLogs.map((l) => l.date.toISOString().slice(0, 10)),\n  ]);\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n\n  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();\n  const days = [];\n  for (let d = 1; d <= daysInMonth; d++) {\n    const date = new Date(Date.UTC(year, month - 1, d));\n    const key = date.toISOString().slice(0, 10);\n    const due =\n      (camp.startDate ? date.getTime() >= toDayStart(camp.startDate).getTime() : true) &&\n      (camp.endDate ? date.getTime() <= toDayStart(camp.endDate).getTime() : true) &&\n      (camp.exercises.some((ce) => isDueOnDate(ce, date)) || camp.circuits.some((c) => isDueOnDate(c, date)));\n    days.push({\n      date: key,\n      due,\n      done: doneDates.has(key),\n      rest: restDates.has(key),\n    });\n  }\n\n  res.json({ month: monthParam, days });\n});\n\n// Fil d\'activite du camp : dernieres seances validees par tous les membres (avec reactions),\n// pour s\'encourager sans se comparer sur la performance.\nrouter.get("/:id/feed", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const [logs, circuitLogs] = await Promise.all([\n    prisma.exerciseLog.findMany({\n      where: { campId },\n      include: { user: { select: { id: true, name: true } }, exercise: { select: { name: true } } },\n      orderBy: { createdAt: "desc" },\n      take: 30,\n    }),\n    prisma.campCircuitLog.findMany({\n      where: { campId },\n      include: { user: { select: { id: true, name: true } }, campCircuit: { select: { name: true } } },\n      orderBy: { createdAt: "desc" },\n      take: 30,\n    }),\n  ]);\n\n  const feedItemsRaw = [\n    ...logs.map((l) => ({\n      targetType: "exercise" as const,\n      targetId: l.id,\n      userId: l.user.id,\n      userName: l.user.name,\n      label: l.exercise.name,\n      date: l.date.toISOString(),\n      createdAt: l.createdAt,\n    })),\n    ...circuitLogs.map((l) => ({\n      targetType: "circuit" as const,\n      targetId: l.id,\n      userId: l.user.id,\n      userName: l.user.name,\n      label: l.campCircuit.name,\n      date: l.date.toISOString(),\n      createdAt: l.createdAt,\n    })),\n  ]\n    .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())\n    .slice(0, 30);\n\n  const reactions = await prisma.reaction.findMany({\n    where: {\n      OR: feedItemsRaw.map((i) => ({ targetType: i.targetType, targetId: i.targetId })),\n    },\n  });\n\n  const feedItems = feedItemsRaw.map((item) => {\n    const itemReactions = reactions.filter((r) => r.targetType === item.targetType && r.targetId === item.targetId);\n    const byType = new Map<string, { count: number; reactedByMe: boolean }>();\n    for (const r of itemReactions) {\n      const entry = byType.get(r.type) ?? { count: 0, reactedByMe: false };\n      entry.count++;\n      if (r.userId === req.userId) entry.reactedByMe = true;\n      byType.set(r.type, entry);\n    }\n    return {\n      ...item,\n      reactions: [...byType.entries()].map(([type, v]) => ({ type, ...v })),\n    };\n  });\n\n  res.json(feedItems);\n});\n\nexport default router;\n'
FILES['backend/src/routes/campMessages.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { sendPushToUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nasync function assertMember(userId: string, campId: string) {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId, campId } },\n  });\n  return !!membership;\n}\n\n// Liste les messages du camp (les plus recents en dernier), reserve aux membres du camp\nrouter.get("/:campId/messages", async (req: AuthRequest, res) => {\n  const { campId } = req.params;\n  if (!(await assertMember(req.userId!, campId))) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const messages = await prisma.campMessage.findMany({\n    where: { campId },\n    include: { user: { select: { id: true, name: true } } },\n    orderBy: { createdAt: "asc" },\n    take: 200, // garde-fou simple : les 200 derniers messages\n  });\n\n  res.json(messages);\n});\n\nconst sendSchema = z.object({ body: z.string().min(1).max(2000) });\n\n// Envoie un message dans le camp, reserve aux membres du camp\nrouter.post("/:campId/messages", async (req: AuthRequest, res) => {\n  const { campId } = req.params;\n  if (!(await assertMember(req.userId!, campId))) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const parsed = sendSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Le message ne peut pas etre vide." });\n  }\n\n  const message = await prisma.campMessage.create({\n    data: { campId, userId: req.userId!, body: parsed.data.body.trim() },\n    include: { user: { select: { id: true, name: true } } },\n  });\n\n  // Notifie les autres membres du camp (pas l\'expediteur), sans bloquer la reponse\n  prisma.camp.findUnique({ where: { id: campId } }).then((camp) => {\n    prisma.campMembership\n      .findMany({ where: { campId, userId: { not: req.userId } } })\n      .then((others) => {\n        const preview = message.body.length > 80 ? `${message.body.slice(0, 80)}…` : message.body;\n        for (const m of others) {\n          sendPushToUser(m.userId, `💬 ${camp?.name ?? "Camp"}`, `${message.user.name} : ${preview}`).catch(() => {});\n        }\n      });\n  });\n\n  res.status(201).json(message);\n});\n\nexport default router;\n'
FILES['backend/src/routes/messages.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { sendPushToUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie la liste des personnes avec qui on peut discuter : celles qui partagent\n// au moins un camp avec l\'utilisateur (on ne permet pas d\'ecrire a un inconnu).\nrouter.get("/contacts", async (req: AuthRequest, res) => {\n  const myMemberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    select: { campId: true },\n  });\n  const campIds = myMemberships.map((m) => m.campId);\n\n  if (campIds.length === 0) return res.json([]);\n\n  const otherMemberships = await prisma.campMembership.findMany({\n    where: { campId: { in: campIds }, userId: { not: req.userId } },\n    include: { user: { select: { id: true, name: true } } },\n  });\n\n  const contactsById = new Map(otherMemberships.map((m) => [m.user.id, m.user]));\n  res.json([...contactsById.values()]);\n});\n\nasync function assertContact(userId: string, otherUserId: string): Promise<boolean> {\n  const shared = await prisma.campMembership.findFirst({\n    where: {\n      userId: otherUserId,\n      camp: { members: { some: { userId } } },\n    },\n  });\n  return !!shared;\n}\n\n// Recupere la conversation avec un utilisateur donne (dans les deux sens)\nrouter.get("/:userId", async (req: AuthRequest, res) => {\n  const otherUserId = req.params.userId;\n  if (!(await assertContact(req.userId!, otherUserId))) {\n    return res.status(403).json({ error: "Vous ne partagez aucun camp ensemble." });\n  }\n\n  const messages = await prisma.directMessage.findMany({\n    where: {\n      OR: [\n        { senderId: req.userId, recipientId: otherUserId },\n        { senderId: otherUserId, recipientId: req.userId },\n      ],\n    },\n    orderBy: { createdAt: "asc" },\n    take: 300,\n  });\n\n  res.json(messages);\n});\n\nconst sendSchema = z.object({ recipientId: z.string(), body: z.string().min(1).max(2000) });\n\n// Envoie un message prive, uniquement possible si les deux utilisateurs partagent un camp\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = sendSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Message invalide." });\n  }\n  const { recipientId, body } = parsed.data;\n\n  if (recipientId === req.userId) {\n    return res.status(400).json({ error: "Impossible de s\'envoyer un message a soi-meme." });\n  }\n  if (!(await assertContact(req.userId!, recipientId))) {\n    return res.status(403).json({ error: "Vous ne partagez aucun camp ensemble." });\n  }\n\n  const message = await prisma.directMessage.create({\n    data: { senderId: req.userId!, recipientId, body: body.trim() },\n  });\n\n  const sender = await prisma.user.findUnique({ where: { id: req.userId } });\n  const preview = body.trim().length > 80 ? `${body.trim().slice(0, 80)}…` : body.trim();\n  sendPushToUser(recipientId, `💬 Message de ${sender?.name ?? ""}`, preview).catch(() => {});\n\n  res.status(201).json(message);\n});\n\nexport default router;\n'
FILES['backend/src/routes/restDays.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Liste les jours de repos de l\'utilisateur (utile pour l\'affichage calendrier)\nrouter.get("/", async (req: AuthRequest, res) => {\n  const restDays = await prisma.restDay.findMany({\n    where: { userId: req.userId },\n    orderBy: { date: "desc" },\n  });\n  res.json(restDays);\n});\n\nconst createSchema = z.object({\n  date: z.string().optional(), // par defaut aujourd\'hui\n  reason: z.string().max(200).optional().nullable(),\n});\n\n// Marque un jour comme "repos justifie" : ce jour ne cassera pas les series de regularite\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Requete invalide." });\n  }\n  const day = toDayStart(parsed.data.date ? new Date(parsed.data.date) : new Date());\n\n  const restDay = await prisma.restDay.upsert({\n    where: { userId_date: { userId: req.userId!, date: day } },\n    create: { userId: req.userId!, date: day, reason: parsed.data.reason ?? null },\n    update: { reason: parsed.data.reason ?? null },\n  });\n\n  res.status(201).json(restDay);\n});\n\n// Retire le statut "repos" d\'un jour (ex: marque par erreur)\nrouter.delete("/", async (req: AuthRequest, res) => {\n  const dateStr = req.query.date as string | undefined;\n  const day = toDayStart(dateStr ? new Date(dateStr) : new Date());\n\n  await prisma.restDay.deleteMany({ where: { userId: req.userId, date: day } });\n  res.status(204).send();\n});\n\nexport default router;\n'
FILES['backend/src/routes/reactions.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { REACTION_CATALOG, REACTION_KEYS } from "../utils/reactions";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nrouter.get("/catalog", (_req, res) => {\n  res.json(REACTION_CATALOG);\n});\n\nconst toggleSchema = z.object({\n  targetType: z.enum(["exercise", "circuit"]),\n  targetId: z.string(),\n  type: z.enum(REACTION_KEYS as [string, ...string[]]),\n});\n\n// Ajoute ou retire une reaction (bascule) sur une seance validee par un membre du meme camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = toggleSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Reaction invalide." });\n  }\n  const { targetType, targetId, type } = parsed.data;\n\n  // Verifie que la cible existe et recupere son camp, pour s\'assurer que l\'utilisateur\n  // en est bien membre (on ne peut reagir qu\'aux seances de ses propres camps).\n  let campId: string | null = null;\n  if (targetType === "exercise") {\n    const log = await prisma.exerciseLog.findUnique({ where: { id: targetId } });\n    campId = log?.campId ?? null;\n  } else {\n    const log = await prisma.campCircuitLog.findUnique({ where: { id: targetId } });\n    campId = log?.campId ?? null;\n  }\n  if (!campId) return res.status(404).json({ error: "Seance introuvable." });\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const existing = await prisma.reaction.findUnique({\n    where: { userId_targetType_targetId_type: { userId: req.userId!, targetType, targetId, type } },\n  });\n\n  if (existing) {\n    await prisma.reaction.delete({ where: { id: existing.id } });\n    return res.json({ active: false });\n  }\n\n  await prisma.reaction.create({ data: { userId: req.userId!, targetType, targetId, type } });\n  res.status(201).json({ active: true });\n});\n\nexport default router;\n'
FILES['backend/src/routes/favoriteCircuits.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Liste les circuits favoris de l\'utilisateur\nrouter.get("/", async (req: AuthRequest, res) => {\n  const favorites = await prisma.favoriteCircuit.findMany({\n    where: { userId: req.userId },\n    orderBy: { createdAt: "desc" },\n  });\n  res.json(favorites);\n});\n\nconst createSchema = z.object({\n  name: z.string().min(1).max(100),\n  items: z.array(z.string().min(1)).min(1),\n  workSeconds: z.number().min(1),\n  restSeconds: z.number().min(0),\n  rounds: z.number().min(1),\n  roundRestSeconds: z.number().min(0),\n});\n\n// Sauvegarde un circuit construit dans l\'onglet Chrono, pour le relancer plus tard\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const data = parsed.data;\n\n  const favorite = await prisma.favoriteCircuit.create({\n    data: {\n      userId: req.userId!,\n      name: data.name,\n      items: JSON.stringify(data.items),\n      workSeconds: data.workSeconds,\n      restSeconds: data.restSeconds,\n      rounds: data.rounds,\n      roundRestSeconds: data.roundRestSeconds,\n    },\n  });\n  res.status(201).json(favorite);\n});\n\n// Supprime un circuit favori\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const favorite = await prisma.favoriteCircuit.findUnique({ where: { id: req.params.id } });\n  if (!favorite || favorite.userId !== req.userId) {\n    return res.status(404).json({ error: "Circuit favori introuvable." });\n  }\n  await prisma.favoriteCircuit.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\nexport default router;\n'
FILES['backend/src/routes/activity.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Historique complet de l\'activite de l\'utilisateur (exercices individuels, circuits de camp,\n// seances chrono libres), avec quelques statistiques agregees. Sert de "carnet d\'entrainement".\nrouter.get("/", async (req: AuthRequest, res) => {\n  const userId = req.userId!;\n\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({\n      where: { userId },\n      include: { exercise: true, camp: { select: { name: true } } },\n      orderBy: { date: "desc" },\n    }),\n    prisma.campCircuitLog.findMany({\n      where: { userId },\n      include: { campCircuit: { select: { name: true } }, camp: { select: { name: true } } },\n      orderBy: { date: "desc" },\n    }),\n    prisma.chronoSession.findMany({\n      where: { userId },\n      orderBy: { completedAt: "desc" },\n    }),\n  ]);\n\n  const items = [\n    ...exerciseLogs.map((l) => ({\n      type: "exercise" as const,\n      date: l.date.toISOString(),\n      exerciseName: l.exercise.name,\n      unit: l.exercise.unit,\n      campName: l.camp.name,\n      setsDone: l.setsDone,\n      valueDone: l.valueDone,\n    })),\n    ...circuitLogs.map((l) => ({\n      type: "circuit" as const,\n      date: l.date.toISOString(),\n      circuitName: l.campCircuit.name,\n      campName: l.camp.name,\n      durationSeconds: l.durationSeconds,\n    })),\n    ...chronoSessions.map((s) => ({\n      type: "chrono" as const,\n      date: s.completedAt.toISOString(),\n      name: s.name,\n      items: JSON.parse(s.items) as string[],\n      totalDurationSeconds: s.totalDurationSeconds,\n      rounds: s.rounds,\n    })),\n  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());\n\n  // Statistiques agregees\n  const totalSessions = exerciseLogs.length + circuitLogs.length + chronoSessions.length;\n\n  // Temps de pratique : uniquement ce qui est mesurable (exercices en secondes + circuits + chrono libre).\n  // Les exercices en repetitions n\'ont pas de duree intrinseque, ils comptent dans le nombre de seances\n  // mais pas dans le temps total.\n  const exerciseSeconds = exerciseLogs\n    .filter((l) => l.exercise.unit === "SECONDS")\n    .reduce((sum, l) => sum + l.setsDone * l.valueDone, 0);\n  const circuitSeconds = circuitLogs.reduce((sum, l) => sum + l.durationSeconds, 0);\n  const chronoSeconds = chronoSessions.reduce((sum, s) => sum + s.totalDurationSeconds, 0);\n  const totalPracticeSeconds = exerciseSeconds + circuitSeconds + chronoSeconds;\n\n  const exerciseNames = new Set(exerciseLogs.map((l) => l.exercise.name));\n\n  // Record personnel par exercice : la meilleure valeur realisee sur UNE serie (pas le cumul)\n  const bestByExercise = new Map<string, { exerciseName: string; unit: string; best: number }>();\n  for (const l of exerciseLogs) {\n    const current = bestByExercise.get(l.exerciseId);\n    if (!current || l.valueDone > current.best) {\n      bestByExercise.set(l.exerciseId, { exerciseName: l.exercise.name, unit: l.exercise.unit, best: l.valueDone });\n    }\n  }\n\n  res.json({\n    stats: {\n      totalSessions,\n      totalPracticeSeconds,\n      exerciseCount: exerciseNames.size,\n      personalBests: [...bestByExercise.values()],\n    },\n    items,\n  });\n});\n\nfunction csvEscape(value: string): string {\n  if (/[",\\n]/.test(value)) return `"${value.replace(/"/g, \'""\')}"`;\n  return value;\n}\n\n// Export CSV de tout l\'historique de l\'utilisateur (exercices, circuits, chrono libre)\nrouter.get("/export.csv", async (req: AuthRequest, res) => {\n  const userId = req.userId!;\n\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({\n      where: { userId },\n      include: { exercise: true, camp: { select: { name: true } } },\n      orderBy: { date: "asc" },\n    }),\n    prisma.campCircuitLog.findMany({\n      where: { userId },\n      include: { campCircuit: { select: { name: true } }, camp: { select: { name: true } } },\n      orderBy: { date: "asc" },\n    }),\n    prisma.chronoSession.findMany({ where: { userId }, orderBy: { completedAt: "asc" } }),\n  ]);\n\n  const rows: string[] = ["date,type,nom,camp,series,valeur,unite,duree_secondes"];\n\n  for (const l of exerciseLogs) {\n    rows.push(\n      [\n        l.date.toISOString().slice(0, 10),\n        "exercice",\n        csvEscape(l.exercise.name),\n        csvEscape(l.camp.name),\n        String(l.setsDone),\n        String(l.valueDone),\n        l.exercise.unit,\n        "",\n      ].join(",")\n    );\n  }\n  for (const l of circuitLogs) {\n    rows.push(\n      [\n        l.date.toISOString().slice(0, 10),\n        "circuit_camp",\n        csvEscape(l.campCircuit.name),\n        csvEscape(l.camp.name),\n        "",\n        "",\n        "",\n        String(l.durationSeconds),\n      ].join(",")\n    );\n  }\n  for (const s of chronoSessions) {\n    rows.push(\n      [\n        s.completedAt.toISOString().slice(0, 10),\n        "chrono_libre",\n        csvEscape(s.name || "Circuit libre"),\n        "",\n        String(s.rounds),\n        "",\n        "",\n        String(s.totalDurationSeconds),\n      ].join(",")\n    );\n  }\n\n  const csv = rows.join("\\n");\n  res.setHeader("Content-Type", "text/csv; charset=utf-8");\n  res.setHeader("Content-Disposition", `attachment; filename="goteam-historique.csv"`);\n  res.send(csv);\n});\n\nexport default router;\n'
FILES['backend/src/routes/progress.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { computeStreak, isDueOnDate, toDayStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Historique + serie de regularite (streak) pour un exercice donne dans un camp.\n// La consigne (recurrence, objectif) est celle definie par le createur du camp ;\n// l\'historique et le streak restent propres a chaque utilisateur.\nrouter.get("/exercise", async (req: AuthRequest, res) => {\n  const campId = req.query.campId as string;\n  const exerciseId = req.query.exerciseId as string;\n  if (!campId || !exerciseId) {\n    return res.status(400).json({ error: "campId et exerciseId sont requis." });\n  }\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const campExercise = await prisma.campExercise.findUnique({\n    where: { campId_exerciseId: { campId, exerciseId } },\n  });\n  if (!campExercise) return res.status(404).json({ error: "Cet exercice ne fait pas partie du camp." });\n\n  const logs = await prisma.exerciseLog.findMany({\n    where: { userId: req.userId, campId, exerciseId },\n    orderBy: { date: "asc" },\n  });\n  const restDays = await prisma.restDay.findMany({ where: { userId: req.userId } });\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n\n  const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n  const streak = computeStreak(campExercise, completedDates, new Date(), restDates);\n\n  // Taux de regularite depuis le debut de la consigne : jours dus vs jours reussis\n  // (les jours de repos justifie ne comptent pas comme "dus")\n  const today = toDayStart(new Date());\n  let dueCount = 0;\n  let doneCount = 0;\n  const cursor = toDayStart(campExercise.startDate);\n  while (cursor.getTime() <= today.getTime()) {\n    const key = cursor.toISOString().slice(0, 10);\n    if (!restDates.has(key) && isDueOnDate(campExercise, cursor)) {\n      dueCount++;\n      if (completedDates.has(key)) doneCount++;\n    }\n    cursor.setUTCDate(cursor.getUTCDate() + 1);\n  }\n  const regularityRate = dueCount > 0 ? Math.round((doneCount / dueCount) * 100) : 0;\n\n  res.json({\n    program: campExercise,\n    history: logs.map((l) => ({\n      date: l.date.toISOString().slice(0, 10),\n      setsDone: l.setsDone,\n      valueDone: l.valueDone,\n    })),\n    streak,\n    dueCount,\n    doneCount,\n    regularityRate,\n  });\n});\n\nexport default router;\n'
FILES['backend/src/services/notifications.ts'] = 'import cron from "node-cron";\nimport webpush from "web-push";\nimport { prisma } from "../lib/prisma";\nimport { isDueOnDate, toDayStart } from "../utils/recurrence";\n\n// Configure web-push avec les cles VAPID (a generer avec `npm run vapid:generate`)\nexport function initPush() {\n  const publicKey = process.env.VAPID_PUBLIC_KEY;\n  const privateKey = process.env.VAPID_PRIVATE_KEY;\n  const subject = process.env.VAPID_SUBJECT || "mailto:contact@example.com";\n\n  if (!publicKey || !privateKey) {\n    console.warn(\n      "[push] Cles VAPID manquantes : les notifications push sont desactivees. " +\n        "Genere-les avec `npm run vapid:generate` et renseigne .env"\n    );\n    return;\n  }\n  webpush.setVapidDetails(subject, publicKey, privateKey);\n  console.log("[push] Notifications push configurees.");\n}\n\n// Verifie, pour chaque utilisateur, les exercices dus aujourd\'hui (selon la consigne du camp)\n// et pas encore faits, puis envoie une notification de rappel groupee.\nexport async function sendDailyReminders() {\n  const today = toDayStart(new Date());\n\n  const memberships = await prisma.campMembership.findMany({\n    include: {\n      user: { include: { subscriptions: true } },\n      camp: { include: { exercises: { include: { exercise: true } } } },\n    },\n  });\n\n  const dueByUser = new Map<string, { name: string }[]>();\n\n  for (const membership of memberships) {\n    const { camp, userId } = membership;\n    if (camp.startDate && today.getTime() < toDayStart(camp.startDate).getTime()) continue;\n    if (camp.endDate && today.getTime() > toDayStart(camp.endDate).getTime()) continue;\n\n    for (const ce of camp.exercises) {\n      if (!isDueOnDate(ce, today)) continue;\n\n      const alreadyLogged = await prisma.exerciseLog.findUnique({\n        where: {\n          userId_campId_exerciseId_date: {\n            userId,\n            campId: ce.campId,\n            exerciseId: ce.exerciseId,\n            date: today,\n          },\n        },\n      });\n      if (alreadyLogged) continue;\n\n      const list = dueByUser.get(userId) || [];\n      list.push({ name: ce.exercise.name });\n      dueByUser.set(userId, list);\n    }\n  }\n\n  const subscriptionsByUser = new Map(memberships.map((m) => [m.userId, m.user.subscriptions]));\n\n  for (const [userId, pending] of dueByUser) {\n    if (pending.length === 0) continue;\n    const subscriptions = subscriptionsByUser.get(userId) ?? [];\n    if (subscriptions.length === 0) continue;\n\n    const names = [...new Set(pending.map((p) => p.name))];\n    const payload = JSON.stringify({\n      title: "C\'est le moment de faire votre seance ! 💪",\n      body:\n        names.length === 1\n          ? `${names[0]} t\'attend aujourd\'hui.`\n          : `${names.slice(0, 3).join(", ")}${names.length > 3 ? "…" : ""} t\'attendent aujourd\'hui.`,\n    });\n\n    for (const sub of subscriptions) {\n      try {\n        await webpush.sendNotification(\n          { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },\n          payload\n        );\n      } catch (err: any) {\n        // Abonnement expire ou invalide : on le retire\n        if (err.statusCode === 404 || err.statusCode === 410) {\n          await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n        } else {\n          console.error("[push] Erreur d\'envoi :", err.message);\n        }\n      }\n    }\n  }\n}\n\n// Planifie l\'envoi quotidien a l\'heure configuree (REMINDER_HOUR, defaut 18h, heure serveur)\nexport function scheduleReminders() {\n  const hour = Number(process.env.REMINDER_HOUR ?? 18);\n  const cronExpr = `0 ${hour} * * *`;\n  cron.schedule(cronExpr, () => {\n    sendDailyReminders().catch((err) => console.error("[push] Erreur lors de l\'envoi des rappels :", err));\n  });\n  console.log(`[push] Rappels quotidiens planifies a ${hour}h (heure serveur).`);\n}\n\n// Envoie une notification a UN utilisateur precis (tous ses appareils abonnes), avec un\n// titre/corps libres. Utilise pour prevenir d\'un nouveau message (camp ou prive).\nexport async function sendPushToUser(userId: string, title: string, body: string) {\n  const subscriptions = await prisma.pushSubscription.findMany({ where: { userId } });\n  if (subscriptions.length === 0) return;\n\n  const payload = JSON.stringify({ title, body });\n  for (const sub of subscriptions) {\n    try {\n      await webpush.sendNotification({ endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } }, payload);\n    } catch (err: any) {\n      if (err.statusCode === 404 || err.statusCode === 410) {\n        await prisma.pushSubscription.delete({ where: { id: sub.id } }).catch(() => {});\n      } else {\n        console.error("[push] Erreur d\'envoi :", err.message);\n      }\n    }\n  }\n}\n'
FILES['backend/src/services/email.ts'] = '// Envoi d\'email minimal. Utilise Resend (https://resend.com, offre gratuite suffisante pour\n// un usage personnel) si RESEND_API_KEY est configuree dans les variables d\'environnement.\n// Sinon, affiche simplement le contenu dans les logs du serveur (pratique en developpement,\n// mais insuffisant en production reelle : pense a configurer RESEND_API_KEY sur Railway).\nexport async function sendEmail(to: string, subject: string, text: string): Promise<void> {\n  const apiKey = process.env.RESEND_API_KEY;\n  const from = process.env.RESEND_FROM_EMAIL || "GoTeam <onboarding@resend.dev>";\n\n  if (!apiKey) {\n    console.warn(\n      `[email] RESEND_API_KEY non configuree : email non envoye, contenu affiche ci-dessous.\\n` +\n        `[email] A: ${to}\\n[email] Sujet: ${subject}\\n[email] Corps:\\n${text}`\n    );\n    return;\n  }\n\n  try {\n    const res = await fetch("https://api.resend.com/emails", {\n      method: "POST",\n      headers: {\n        Authorization: `Bearer ${apiKey}`,\n        "Content-Type": "application/json",\n      },\n      body: JSON.stringify({ from, to, subject, text }),\n    });\n    if (!res.ok) {\n      const body = await res.text();\n      console.error("[email] Echec de l\'envoi via Resend :", res.status, body);\n    }\n  } catch (err) {\n    console.error("[email] Erreur lors de l\'envoi :", err);\n  }\n}\n'
FILES['backend/src/utils/badges.ts'] = 'import { prisma } from "../lib/prisma";\nimport { toDayStart } from "./recurrence";\n\n// Catalogue des badges disponibles. Purement individuel : aucune comparaison entre utilisateurs.\nexport interface BadgeDefinition {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport const BADGE_CATALOG: BadgeDefinition[] = [\n  { key: "STREAK_3", name: "3 jours d\'affilee", description: "Une seance realisee chaque jour, 3 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_7", name: "1 semaine reguliere", description: "Une seance realisee chaque jour, 7 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_30", name: "1 mois de regularite", description: "Une seance realisee chaque jour, 30 jours de suite.", emoji: "🏅" },\n  { key: "STREAK_100", name: "100 jours de suite", description: "Une seance realisee chaque jour, 100 jours de suite.", emoji: "🏆" },\n  { key: "TOTAL_10", name: "10 seances", description: "10 seances validees au total.", emoji: "✅" },\n  { key: "TOTAL_50", name: "50 seances", description: "50 seances validees au total.", emoji: "⭐" },\n  { key: "TOTAL_100", name: "100 seances", description: "100 seances validees au total.", emoji: "🌟" },\n  { key: "TOTAL_500", name: "500 seances", description: "500 seances validees au total.", emoji: "💎" },\n];\n\nconst STREAK_THRESHOLDS: [number, string][] = [\n  [100, "STREAK_100"],\n  [30, "STREAK_30"],\n  [7, "STREAK_7"],\n  [3, "STREAK_3"],\n];\n\nconst TOTAL_THRESHOLDS: [number, string][] = [\n  [500, "TOTAL_500"],\n  [100, "TOTAL_100"],\n  [50, "TOTAL_50"],\n  [10, "TOTAL_10"],\n];\n\n// Calcule le plus long "streak" en cours (jours consecutifs avec au moins une seance,\n// tous camps/exercices confondus), en remontant depuis aujourd\'hui ou hier. Les jours\n// marques comme "repos justifie" sont neutres : ils n\'interrompent pas la serie.\nfunction computeGlobalStreak(distinctDates: Set<string>, today: Date, restDates: Set<string> = new Set()): number {\n  const start = toDayStart(today);\n  // Si rien n\'est fait aujourd\'hui, on tolere et on part d\'hier pour ne pas casser la serie\n  // en cours de journee.\n  let cursor = new Date(start);\n  if (!distinctDates.has(cursor.toISOString().slice(0, 10)) && !restDates.has(cursor.toISOString().slice(0, 10))) {\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  let streak = 0;\n  for (let i = 0; i < 3650; i++) {\n    const key = cursor.toISOString().slice(0, 10);\n    if (restDates.has(key)) {\n      cursor.setUTCDate(cursor.getUTCDate() - 1);\n      continue;\n    }\n    if (!distinctDates.has(key)) break;\n    streak++;\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  return streak;\n}\n\n// Recalcule les stats de l\'utilisateur et attribue tout nouveau badge merite.\n// Appele apres chaque validation de seance (exercice, circuit de camp, ou seance chrono libre).\n// Idempotent (un badge n\'est jamais attribue deux fois).\nexport async function checkAndAwardBadges(userId: string): Promise<BadgeDefinition[]> {\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.campCircuitLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.chronoSession.findMany({ where: { userId }, select: { completedAt: true } }),\n  ]);\n\n  const distinctDates = new Set<string>([\n    ...exerciseLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...circuitLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...chronoSessions.map((s) => s.completedAt.toISOString().slice(0, 10)),\n  ]);\n  const totalSessions = exerciseLogs.length + circuitLogs.length + chronoSessions.length;\n  const restDays = await prisma.restDay.findMany({ where: { userId }, select: { date: true } });\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n  const streak = computeGlobalStreak(distinctDates, new Date(), restDates);\n\n  const earnedKeys = new Set<string>();\n  // On attribue TOUS les paliers deja franchis (pas seulement le plus haut), pour garder\n  // l\'historique des badges obtenus meme si la serie casse ensuite.\n  for (const [threshold, key] of STREAK_THRESHOLDS) {\n    if (streak >= threshold) earnedKeys.add(key);\n  }\n  for (const [threshold, key] of TOTAL_THRESHOLDS) {\n    if (totalSessions >= threshold) earnedKeys.add(key);\n  }\n\n  if (earnedKeys.size === 0) return [];\n\n  const alreadyEarned = await prisma.userBadge.findMany({ where: { userId }, select: { badgeKey: true } });\n  const alreadyEarnedKeys = new Set(alreadyEarned.map((b) => b.badgeKey));\n\n  const newlyEarned = [...earnedKeys].filter((k) => !alreadyEarnedKeys.has(k));\n  if (newlyEarned.length === 0) return [];\n\n  await prisma.userBadge.createMany({\n    data: newlyEarned.map((badgeKey) => ({ userId, badgeKey })),\n  });\n\n  return BADGE_CATALOG.filter((b) => newlyEarned.includes(b.key));\n}\n'
FILES['backend/src/utils/reactions.ts'] = 'export interface ReactionDefinition {\n  key: string;\n  label: string;\n  emoji: string;\n}\n\n// Inspire des chants/rituels de supporters : encourager, pas comparer les performances.\nexport const REACTION_CATALOG: ReactionDefinition[] = [\n  { key: "OVATION", label: "Ovation", emoji: "🙌" },\n  { key: "RESPECT", label: "Respect", emoji: "🫡" },\n  { key: "HAKA", label: "Haka", emoji: "💥" },\n  { key: "OLA", label: "Ola", emoji: "🌊" },\n  { key: "HYMNE", label: "Hymne", emoji: "🎶" },\n  { key: "CLAPPING", label: "Clapping", emoji: "👏" },\n  { key: "TIFO", label: "Tifo", emoji: "🎨" },\n  { key: "TAMBOURINAGE", label: "Tambourinage", emoji: "🥁" },\n];\n\nexport const REACTION_KEYS = REACTION_CATALOG.map((r) => r.key);\n'
FILES['backend/src/utils/recurrence.ts'] = '// Logique de recurrence : determine si un programme (exercice + planning)\n// est "du" un jour donne, independamment du fait qu\'il ait ete fait ou non.\n\n// Remarque : type assoupli en "string" (plutot qu\'une union litterale stricte) car le champ\n// correspondant dans la base (voir schema.prisma) est un simple String -- SQLite ne supporte\n// pas les enums natifs. La validation des valeurs autorisees se fait cote API avec zod.\nexport type RecurrenceType = string;\n\nexport interface RecurrenceInput {\n  recurrenceType: RecurrenceType;\n  daysOfWeek?: string | null; // JSON string ex: "[1,3,5]"\n  intervalDays?: number | null;\n  startDate: Date;\n}\n\n// Normalise une date a minuit (UTC) pour comparer uniquement les jours calendaires\nexport function toDayStart(d: Date): Date {\n  const copy = new Date(d);\n  copy.setUTCHours(0, 0, 0, 0);\n  return copy;\n}\n\nexport function daysBetween(a: Date, b: Date): number {\n  const MS_PER_DAY = 24 * 60 * 60 * 1000;\n  return Math.round((toDayStart(b).getTime() - toDayStart(a).getTime()) / MS_PER_DAY);\n}\n\nexport function isDueOnDate(program: RecurrenceInput, date: Date): boolean {\n  const day = toDayStart(date);\n  const start = toDayStart(program.startDate);\n\n  // Un programme n\'est jamais "du" avant sa date de creation\n  if (day.getTime() < start.getTime()) return false;\n\n  switch (program.recurrenceType) {\n    case "DAILY":\n      return true;\n\n    case "WEEKLY": {\n      const days: number[] = program.daysOfWeek ? JSON.parse(program.daysOfWeek) : [];\n      return days.includes(day.getUTCDay());\n    }\n\n    case "EVERY_N_DAYS": {\n      const interval = program.intervalDays && program.intervalDays > 0 ? program.intervalDays : 1;\n      const diff = daysBetween(start, day);\n      return diff % interval === 0;\n    }\n\n    default:\n      return false;\n  }\n}\n\n// Calcule la "regularite" (streak) : nombre de jours consecutifs (en remontant depuis aujourd\'hui)\n// ou l\'exercice etait du et a bien ete complete. On s\'arrete au premier jour du manque.\n// Les jours marques comme "repos justifie" (restDates) sont neutres : ni un manque, ni une reussite,\n// ils n\'interrompent pas la serie.\nexport function computeStreak(\n  program: RecurrenceInput,\n  completedDates: Set<string>, // dates au format YYYY-MM-DD ou l\'exercice a ete complete\n  today: Date,\n  restDates: Set<string> = new Set()\n): number {\n  let streak = 0;\n  const cursor = toDayStart(today);\n\n  // On remonte jour par jour, en ignorant les jours ou l\'exercice n\'etait pas prevu\n  // mais en cassant la serie des qu\'un jour prevu n\'a pas ete fait (sauf jour de repos justifie).\n  for (let i = 0; i < 3650; i++) {\n    const d = new Date(cursor);\n    d.setUTCDate(d.getUTCDate() - i);\n    if (d.getTime() < toDayStart(program.startDate).getTime()) break;\n\n    const key = d.toISOString().slice(0, 10);\n    if (restDates.has(key)) continue; // jour neutre, on passe au suivant sans casser la serie\n\n    if (isDueOnDate(program, d)) {\n      if (completedDates.has(key)) {\n        streak++;\n      } else {\n        // Si c\'est aujourd\'hui et pas encore fait, on ne casse pas la serie\n        // (la journee n\'est pas terminee), on continue juste sans incrementer.\n        if (i === 0) continue;\n        break;\n      }\n    }\n  }\n  return streak;\n}\n'
FILES['backend/.env.example'] = '# Base de donnees (SQLite par defaut, fonctionne "out of the box")\n# Pour passer sur PostgreSQL, changer le "provider" dans prisma/schema.prisma\n# et utiliser une URL du type postgresql://user:password@host:5432/dbname\nDATABASE_URL="file:./dev.db"\n\n# Secret utilise pour signer les tokens JWT (change cette valeur en production !)\nJWT_SECRET="change-moi-en-une-longue-chaine-aleatoire"\n\n# Duree de validite du token, format zeit/ms (ex: "30d", "12h")\nJWT_EXPIRES_IN="30d"\n\n# Port d\'ecoute de l\'API\nPORT=4000\n\n# Origine autorisee pour le CORS (URL du frontend)\nFRONTEND_URL="http://localhost:5173"\n\n# Cles VAPID pour les notifications push (genere-les avec `npm run vapid:generate`)\nVAPID_PUBLIC_KEY=""\nVAPID_PRIVATE_KEY=""\nVAPID_SUBJECT="mailto:contact@example.com"\n\n# Heure (0-23, heure serveur) a laquelle envoyer le rappel quotidien\nREMINDER_HOUR=18\n\n# Optionnel : pour que "mot de passe oublie" envoie de vrais emails (sinon le lien de\n# reinitialisation s\'affiche simplement dans les logs du serveur). Cree un compte gratuit\n# sur https://resend.com, recupere une cle API, et renseigne-la ici.\nRESEND_API_KEY=""\nRESEND_FROM_EMAIL="GoTeam <onboarding@resend.dev>"\n'
FILES['frontend/src/api/client.ts'] = '// Petit client HTTP centralisant l\'appel a l\'API et la gestion du token JWT.\n\nconst API_URL = import.meta.env.VITE_API_URL || "http://localhost:4000/api";\n\nfunction getToken(): string | null {\n  return localStorage.getItem("token");\n}\n\nexport class ApiError extends Error {}\n\nasync function request<T>(path: string, options: RequestInit = {}): Promise<T> {\n  const token = getToken();\n  const res = await fetch(`${API_URL}${path}`, {\n    ...options,\n    headers: {\n      "Content-Type": "application/json",\n      ...(token ? { Authorization: `Bearer ${token}` } : {}),\n      ...(options.headers || {}),\n    },\n  });\n\n  if (res.status === 204) return undefined as T;\n\n  const isJson = res.headers.get("content-type")?.includes("application/json");\n  const body = isJson ? await res.json() : undefined;\n\n  if (!res.ok) {\n    throw new ApiError(body?.error || `Erreur ${res.status}`);\n  }\n  return body as T;\n}\n\nexport const api = {\n  get: <T>(path: string) => request<T>(path, { method: "GET" }),\n  post: <T>(path: string, data?: unknown) =>\n    request<T>(path, { method: "POST", body: data !== undefined ? JSON.stringify(data) : undefined }),\n  put: <T>(path: string, data?: unknown) =>\n    request<T>(path, { method: "PUT", body: JSON.stringify(data) }),\n  del: <T>(path: string) => request<T>(path, { method: "DELETE" }),\n};\n\n// Telecharge un fichier depuis une route protegee (ex: export CSV) en incluant le token,\n// puisqu\'un simple lien <a href> ne peut pas envoyer l\'en-tete Authorization.\nexport async function downloadFile(path: string, filename: string): Promise<void> {\n  const token = getToken();\n  const res = await fetch(`${API_URL}${path}`, {\n    headers: token ? { Authorization: `Bearer ${token}` } : {},\n  });\n  if (!res.ok) throw new ApiError(`Erreur ${res.status}`);\n  const blob = await res.blob();\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement("a");\n  a.href = url;\n  a.download = filename;\n  document.body.appendChild(a);\n  a.click();\n  a.remove();\n  URL.revokeObjectURL(url);\n}\n\nexport { API_URL };\n'
FILES['frontend/src/pages/Today.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\nimport DurationInput from "../components/DurationInput";\nimport CircuitRunner from "../components/CircuitRunner";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface TodayExerciseItem {\n  kind: "exercise";\n  campExerciseId: string;\n  campId: string;\n  campName: string;\n  exerciseId: string;\n  exerciseName: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  personalBest: number | null;\n  done: boolean;\n  log: { setsDone: number; valueDone: number } | null;\n}\n\ninterface TodayCircuitItem {\n  kind: "circuit";\n  campCircuitId: string;\n  campId: string;\n  campName: string;\n  name: string;\n  description: string | null;\n  items: { exerciseId?: string; name: string }[];\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n  done: boolean;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\n// Repos par defaut entre chaque serie lors d\'un chrono rapide lance sur un seul exercice\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nexport default function Today() {\n  const [items, setItems] = useState<TodayExerciseItem[] | null>(null);\n  const [circuits, setCircuits] = useState<TodayCircuitItem[]>([]);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [sets, setSets] = useState(0);\n  const [value, setValue] = useState(0);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n  const [isRestToday, setIsRestToday] = useState(false);\n  const [restBusy, setRestBusy] = useState(false);\n  const [runner, setRunner] = useState<\n    | { type: "exercise"; item: TodayExerciseItem }\n    | { type: "circuit"; item: TodayCircuitItem }\n    | null\n  >(null);\n\n  function load() {\n    api\n      .get<{ date: string; items: TodayExerciseItem[]; circuits: TodayCircuitItem[] }>("/today")\n      .then((res) => {\n        setItems(res.items);\n        setCircuits(res.circuits);\n      });\n  }\n  useEffect(load, []);\n\n  useEffect(() => {\n    const todayKey = new Date().toISOString().slice(0, 10);\n    api.get<{ date: string }[]>("/rest-days").then((days) => {\n      setIsRestToday(days.some((d) => d.date.slice(0, 10) === todayKey));\n    });\n  }, []);\n\n  async function toggleRestDay() {\n    setRestBusy(true);\n    try {\n      if (isRestToday) {\n        await api.del("/rest-days");\n        setIsRestToday(false);\n      } else {\n        await api.post("/rest-days", {});\n        setIsRestToday(true);\n      }\n    } finally {\n      setRestBusy(false);\n    }\n  }\n\n  function startEditing(item: TodayExerciseItem) {\n    setEditingId(item.campExerciseId);\n    setSets(item.log?.setsDone ?? item.targetSets);\n    setValue(item.log?.valueDone ?? item.targetValue ?? item.personalBest ?? 0);\n  }\n\n  async function confirm(item: TodayExerciseItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: sets,\n      valueDone: value,\n    });\n    setEditingId(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function undo(item: TodayExerciseItem) {\n    await api.del(`/logs?campId=${item.campId}&exerciseId=${item.exerciseId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(item: TodayExerciseItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: item.targetSets,\n      valueDone: item.targetValue ?? 0,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function onCircuitComplete(item: TodayCircuitItem, totalDurationSeconds: number) {\n    const res = await api.post<{ newBadges: NewBadge[] }>(`/camp-circuits/${item.campCircuitId}/log`, {\n      durationSeconds: totalDurationSeconds,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  if (runner?.type === "exercise") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: item.exerciseName }]}\n          workSeconds={item.targetValue ?? 30}\n          restSeconds={0}\n          rounds={item.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(item)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runner?.type === "circuit") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={item.items.map((i) => ({ name: i.name }))}\n          workSeconds={item.workSeconds}\n          restSeconds={item.restSeconds}\n          rounds={item.rounds}\n          roundRestSeconds={item.roundRestSeconds}\n          onComplete={(duration) => onCircuitComplete(item, duration)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  const doneCount = (items?.filter((i) => i.done).length ?? 0) + circuits.filter((c) => c.done).length;\n  const total = (items?.length ?? 0) + circuits.length;\n\n  return (\n    <div className="max-w-xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Aujourd\'hui</h1>\n      <p className="text-muted text-sm mb-3">\n        {total === 0\n          ? "Rien de prevu aujourd\'hui."\n          : `${doneCount} / ${total} seance${total > 1 ? "s" : ""} validee${doneCount > 1 ? "s" : ""}.`}\n      </p>\n\n      {isRestToday ? (\n        <div className="bg-success/10 border border-success rounded-xl p-3 mb-5 flex items-center justify-between gap-3">\n          <p className="text-sm">😴 Jour de repos justifie — ta serie de regularite n\'est pas cassee aujourd\'hui.</p>\n          <button\n            onClick={toggleRestDay}\n            disabled={restBusy}\n            className="text-xs text-muted hover:text-accent shrink-0"\n          >\n            Annuler\n          </button>\n        </div>\n      ) : (\n        <button\n          onClick={toggleRestDay}\n          disabled={restBusy}\n          className="text-xs text-muted hover:text-accent mb-5 underline decoration-dotted"\n        >\n          😴 Marquer aujourd\'hui comme jour de repos (blessure, voyage...)\n        </button>\n      )}\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n\n      {items?.length === 0 && circuits.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm mb-3">\n            Aucun exercice programme pour aujourd\'hui. Va voir tes camps pour rejoindre ou creer un camp.\n          </p>\n          <Link to="/camps" className="text-accent hover:text-accentSoft text-sm">\n            Voir mes camps\n          </Link>\n        </div>\n      )}\n\n      {circuits.length > 0 && (\n        <div className="space-y-3 mb-4">\n          {circuits.map((c) => (\n            <div\n              key={c.campCircuitId}\n              className={`bg-surface border rounded-xl p-4 ${c.done ? "border-success/50" : "border-border"}`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">🔁 {c.name}</p>\n                  <p className="text-xs text-muted">\n                    {c.campName} · {c.rounds} tour{c.rounds > 1 ? "s" : ""} · {c.items.length} exercice\n                    {c.items.length > 1 ? "s" : ""}\n                  </p>\n                  {c.description && <p className="text-xs text-muted italic mt-0.5">"{c.description}"</p>}\n                </div>\n                {c.done ? (\n                  <span className="text-success text-sm shrink-0">✓ Fait</span>\n                ) : (\n                  <button\n                    onClick={() => setRunner({ type: "circuit", item: c })}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm shrink-0"\n                  >\n                    ⏱ Lancer\n                  </button>\n                )}\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {items?.map((item) => {\n          const unitLabel = item.unit === "REPS" ? "reps" : "sec";\n          const isEditing = editingId === item.campExerciseId;\n          const canQuickChrono = item.unit === "SECONDS" && item.targetMode === "FIXED" && !item.done;\n          const targetLabel =\n            item.targetMode === "MAX"\n              ? `${item.targetSets} serie${item.targetSets > 1 ? "s" : ""} a fond${\n                  item.personalBest\n                    ? ` (record : ${item.unit === "SECONDS" ? secondsToMMSS(item.personalBest) : item.personalBest} ${unitLabel})`\n                    : ""\n                }`\n              : `${item.targetSets} x ${item.unit === "SECONDS" && item.targetValue ? secondsToMMSS(item.targetValue) : item.targetValue} ${item.unit === "SECONDS" ? "" : unitLabel}`;\n\n          return (\n            <div\n              key={item.campExerciseId}\n              className={`bg-surface border rounded-xl p-4 transition-colors ${\n                item.done ? "border-success/50" : "border-border"\n              }`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">{item.exerciseName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · objectif {targetLabel}\n                  </p>\n                  {item.description && <p className="text-xs text-muted italic mt-0.5">"{item.description}"</p>}\n                </div>\n\n                {!isEditing && (\n                  <div className="flex items-center gap-2 shrink-0">\n                    {canQuickChrono && (\n                      <button\n                        onClick={() => setRunner({ type: "exercise", item })}\n                        title="Lancer le chrono pour cet exercice"\n                        className="w-10 h-10 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                      >\n                        ⏱\n                      </button>\n                    )}\n                    <button\n                      onClick={() => (item.done ? undo(item) : startEditing(item))}\n                      className={`stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 ${\n                        item.done\n                          ? "bg-success/20 border-success text-success"\n                          : "bg-surface2 border-border text-muted hover:border-accent hover:text-accent"\n                      }`}\n                      aria-label={item.done ? "Annuler la validation" : "Valider la seance"}\n                      title={item.done ? "Fait - clique pour annuler" : "Marquer comme fait"}\n                    >\n                      {item.done ? "✓" : ""}\n                    </button>\n                  </div>\n                )}\n              </div>\n\n              {item.done && item.log && (\n                <p className="text-xs text-muted mt-2">\n                  Realise : {item.log.setsDone} x{" "}\n                  {item.unit === "SECONDS" ? secondsToMMSS(item.log.valueDone) : `${item.log.valueDone} ${unitLabel}`}\n                </p>\n              )}\n\n              {isEditing && (\n                <div className="mt-3 flex items-end gap-3 flex-wrap bg-surface2 border border-border rounded-md p-3">\n                  <div>\n                    <label className="block text-xs text-muted mb-1">Series faites</label>\n                    <input\n                      type="number"\n                      min={0}\n                      value={sets}\n                      onChange={(e) => setSets(Number(e.target.value))}\n                      className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                    />\n                  </div>\n                  <div>\n                    <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n                    {item.unit === "SECONDS" ? (\n                      <DurationInput totalSeconds={value} onChange={setValue} />\n                    ) : (\n                      <input\n                        type="number"\n                        min={0}\n                        value={value}\n                        onChange={(e) => setValue(Number(e.target.value))}\n                        className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                      />\n                    )}\n                  </div>\n                  <button\n                    onClick={() => confirm(item)}\n                    className="bg-accent text-bg font-semibold rounded-md px-4 py-1.5 text-sm"\n                  >\n                    Valider\n                  </button>\n                  <button onClick={() => setEditingId(null)} className="text-muted text-sm px-2">\n                    Annuler\n                  </button>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Chrono.tsx'] = 'import { useEffect, useMemo, useRef, useState } from "react";\nimport { api } from "../api/client";\nimport CircuitRunner from "../components/CircuitRunner";\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n  unit: "REPS" | "SECONDS";\n}\n\ninterface CircuitItem {\n  key: string;\n  name: string;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\ninterface FavoriteCircuit {\n  id: string;\n  name: string;\n  items: string; // JSON\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n}\n\nexport default function Chrono() {\n  const [mode, setMode] = useState<"circuit" | "simple">("circuit");\n\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [search, setSearch] = useState("");\n  const [items, setItems] = useState<CircuitItem[]>([]);\n  const [customName, setCustomName] = useState("");\n\n  const [workSeconds, setWorkSeconds] = useState(40);\n  const [restSeconds, setRestSeconds] = useState(20);\n  const [rounds, setRounds] = useState(3);\n  const [roundRestSeconds, setRoundRestSeconds] = useState(60);\n\n  const [isRunningCircuit, setIsRunningCircuit] = useState(false);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n\n  const [favorites, setFavorites] = useState<FavoriteCircuit[]>([]);\n  const [savingFavoriteName, setSavingFavoriteName] = useState<string | null>(null);\n\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n    loadFavorites();\n  }, []);\n\n  function loadFavorites() {\n    api.get<FavoriteCircuit[]>("/favorite-circuits").then(setFavorites);\n  }\n\n  function loadFavorite(fav: FavoriteCircuit) {\n    const names = JSON.parse(fav.items) as string[];\n    setItems(names.map((name) => ({ key: `${name}-${Date.now()}-${Math.random()}`, name })));\n    setWorkSeconds(fav.workSeconds);\n    setRestSeconds(fav.restSeconds);\n    setRounds(fav.rounds);\n    setRoundRestSeconds(fav.roundRestSeconds);\n  }\n\n  async function saveFavorite() {\n    if (!savingFavoriteName?.trim() || items.length === 0) return;\n    await api.post("/favorite-circuits", {\n      name: savingFavoriteName.trim(),\n      items: items.map((i) => i.name),\n      workSeconds,\n      restSeconds,\n      rounds,\n      roundRestSeconds,\n    });\n    setSavingFavoriteName(null);\n    loadFavorites();\n  }\n\n  async function deleteFavorite(id: string) {\n    await api.del(`/favorite-circuits/${id}`);\n    loadFavorites();\n  }\n\n  const filteredCatalog = useMemo(\n    () => catalog.filter((e) => e.name.toLowerCase().includes(search.toLowerCase())),\n    [catalog, search]\n  );\n\n  function addItem(name: string) {\n    setItems((prev) => [...prev, { key: `${name}-${Date.now()}-${Math.random()}`, name }]);\n  }\n\n  async function addCustom() {\n    if (!customName.trim()) return;\n    try {\n      const created = await api.post<CatalogExercise>("/exercises", { name: customName.trim(), unit: "REPS" });\n      setCatalog((prev) => [...prev, created]);\n      addItem(created.name);\n    } catch {\n      addItem(customName.trim());\n    }\n    setCustomName("");\n  }\n\n  function removeItem(key: string) {\n    setItems((prev) => prev.filter((i) => i.key !== key));\n  }\n\n  function moveItem(key: string, direction: -1 | 1) {\n    setItems((prev) => {\n      const index = prev.findIndex((i) => i.key === key);\n      const newIndex = index + direction;\n      if (newIndex < 0 || newIndex >= prev.length) return prev;\n      const copy = [...prev];\n      [copy[index], copy[newIndex]] = [copy[newIndex], copy[index]];\n      return copy;\n    });\n  }\n\n  async function onCircuitComplete(totalDurationSeconds: number) {\n    setIsRunningCircuit(false);\n    try {\n      const res = await api.post<{ newBadges: NewBadge[] }>("/chrono-sessions", {\n        items: items.map((i) => i.name),\n        workSeconds,\n        restSeconds,\n        rounds,\n        roundRestSeconds,\n        totalDurationSeconds,\n      });\n      if (res.newBadges?.length) setCelebrating(res.newBadges);\n    } catch {\n      // meme si l\'enregistrement echoue (ex: hors ligne), on ne bloque pas l\'utilisateur\n    }\n  }\n\n  if (isRunningCircuit) {\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={items.map((i) => ({ name: i.name }))}\n          workSeconds={workSeconds}\n          restSeconds={restSeconds}\n          rounds={rounds}\n          roundRestSeconds={roundRestSeconds}\n          onComplete={onCircuitComplete}\n          onCancel={() => setIsRunningCircuit(false)}\n        />\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-2xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Chronometre</h1>\n      <p className="text-muted text-sm mb-4">\n        Construis ta propre seance en circuit training, ou lance simplement un chrono.\n      </p>\n\n      <div className="flex gap-1.5 mb-6">\n        <button\n          onClick={() => setMode("circuit")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "circuit" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Circuit training\n        </button>\n        <button\n          onClick={() => setMode("simple")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "simple" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Chrono simple\n        </button>\n      </div>\n\n      {mode === "simple" ? (\n        <SimpleTimer />\n      ) : (\n        <div className="grid md:grid-cols-2 gap-6">\n          <div>\n            {favorites.length > 0 && (\n              <div className="mb-5">\n                <h2 className="font-display uppercase tracking-wide text-sm mb-2">Mes circuits favoris</h2>\n                <div className="space-y-1.5">\n                  {favorites.map((fav) => (\n                    <div\n                      key={fav.id}\n                      className="flex items-center justify-between bg-surface border border-border rounded-md px-3 py-2 text-sm"\n                    >\n                      <button onClick={() => loadFavorite(fav)} className="text-left hover:text-accent">\n                        ⭐ {fav.name}\n                      </button>\n                      <button onClick={() => deleteFavorite(fav.id)} className="text-muted hover:text-accent text-xs">\n                        ✕\n                      </button>\n                    </div>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            <h2 className="font-display uppercase tracking-wide text-sm mb-2">1. Choisis tes exercices</h2>\n            <input\n              placeholder="Rechercher un exercice..."\n              value={search}\n              onChange={(e) => setSearch(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-2 text-sm"\n            />\n            <div className="grid grid-cols-2 gap-1.5 max-h-40 overflow-y-auto mb-2">\n              {filteredCatalog.map((exo) => (\n                <button\n                  key={exo.id}\n                  type="button"\n                  onClick={() => addItem(exo.name)}\n                  className="text-left text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-2 py-1.5"\n                >\n                  + {exo.name}\n                </button>\n              ))}\n            </div>\n            <div className="flex gap-2">\n              <input\n                value={customName}\n                onChange={(e) => setCustomName(e.target.value)}\n                placeholder="Nouvel exercice..."\n                className="flex-1 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n              <button\n                type="button"\n                onClick={addCustom}\n                className="bg-accent text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n              >\n                Ajouter\n              </button>\n            </div>\n\n            <h3 className="font-display uppercase tracking-wide text-xs mt-4 mb-2 text-muted">\n              Circuit ({items.length} exercice{items.length > 1 ? "s" : ""})\n            </h3>\n            <div className="space-y-1.5">\n              {items.length === 0 && <p className="text-muted text-sm italic">Aucun exercice ajoute pour l\'instant.</p>}\n              {items.map((item, index) => (\n                <div\n                  key={item.key}\n                  className="flex items-center justify-between bg-surface border border-border rounded-md px-3 py-1.5 text-sm"\n                >\n                  <span>\n                    {index + 1}. {item.name}\n                  </span>\n                  <div className="flex gap-1 items-center">\n                    <button onClick={() => moveItem(item.key, -1)} className="text-muted hover:text-text px-1">\n                      ↑\n                    </button>\n                    <button onClick={() => moveItem(item.key, 1)} className="text-muted hover:text-text px-1">\n                      ↓\n                    </button>\n                    <button onClick={() => removeItem(item.key)} className="text-muted hover:text-accent px-1">\n                      ✕\n                    </button>\n                  </div>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          <div>\n            <h2 className="font-display uppercase tracking-wide text-sm mb-2">2. Reglages du circuit</h2>\n            <div className="bg-surface border border-border rounded-lg p-4 space-y-3">\n              <div>\n                <label className="block text-xs text-muted mb-1">Temps de travail (secondes)</label>\n                <input\n                  type="number"\n                  min={5}\n                  value={workSeconds}\n                  onChange={(e) => setWorkSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Temps de repos entre exercices (secondes)</label>\n                <input\n                  type="number"\n                  min={0}\n                  value={restSeconds}\n                  onChange={(e) => setRestSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Nombre de tours</label>\n                <input\n                  type="number"\n                  min={1}\n                  value={rounds}\n                  onChange={(e) => setRounds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Repos entre chaque tour (secondes)</label>\n                <input\n                  type="number"\n                  min={0}\n                  value={roundRestSeconds}\n                  onChange={(e) => setRoundRestSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n            </div>\n\n            <button\n              onClick={() => setIsRunningCircuit(true)}\n              disabled={items.length === 0}\n              className="w-full mt-4 bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2.5 disabled:opacity-50"\n            >\n              Lancer le circuit\n            </button>\n\n            {savingFavoriteName !== null ? (\n              <div className="flex gap-2 mt-2">\n                <input\n                  value={savingFavoriteName}\n                  onChange={(e) => setSavingFavoriteName(e.target.value)}\n                  placeholder="Nom du circuit favori..."\n                  className="flex-1 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n                <button onClick={saveFavorite} className="bg-surface2 hover:bg-border border border-border rounded-md px-3 py-1.5 text-sm">\n                  OK\n                </button>\n                <button onClick={() => setSavingFavoriteName(null)} className="text-muted text-sm px-2">\n                  ✕\n                </button>\n              </div>\n            ) : (\n              <button\n                onClick={() => setSavingFavoriteName("")}\n                disabled={items.length === 0}\n                className="w-full mt-2 text-sm text-accent hover:text-accentSoft disabled:opacity-40"\n              >\n                ⭐ Sauvegarder ce circuit en favori\n              </button>\n            )}\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\n// Chrono simple : un minuteur (compte a rebours) ou chronometre (compte en avant si duree = 0),\n// pour un usage ponctuel sans construire tout un circuit.\nfunction SimpleTimer() {\n  const [inputMinutes, setInputMinutes] = useState(1);\n  const [inputSeconds, setInputSeconds] = useState(0);\n  const [remaining, setRemaining] = useState(60);\n  const [running, setRunning] = useState(false);\n  const [countUp, setCountUp] = useState(false);\n  const intervalRef = useRef<number | null>(null);\n\n  function applySettings() {\n    const total = inputMinutes * 60 + inputSeconds;\n    setCountUp(total === 0);\n    setRemaining(total === 0 ? 0 : total);\n    setRunning(false);\n  }\n\n  useEffect(() => {\n    if (!running) return;\n    intervalRef.current = window.setInterval(() => {\n      setRemaining((r) => {\n        if (countUp) return r + 1;\n        if (r <= 1) {\n          setRunning(false);\n          try {\n            const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;\n            const ctx = new AudioCtx();\n            const osc = ctx.createOscillator();\n            osc.frequency.value = 660;\n            osc.connect(ctx.destination);\n            osc.start();\n            osc.stop(ctx.currentTime + 0.4);\n            osc.onended = () => ctx.close();\n          } catch {\n            /* pas grave si pas de son */\n          }\n          return 0;\n        }\n        return r - 1;\n      });\n    }, 1000);\n    return () => {\n      if (intervalRef.current) window.clearInterval(intervalRef.current);\n    };\n  }, [running, countUp]);\n\n  const mm = Math.floor(remaining / 60);\n  const ss = remaining % 60;\n\n  return (\n    <div className="max-w-sm mx-auto text-center">\n      <div className="border-4 border-accent rounded-full w-56 h-56 mx-auto flex flex-col items-center justify-center my-6">\n        <p className="font-display text-6xl">\n          {mm}:{ss.toString().padStart(2, "0")}\n        </p>\n      </div>\n\n      <div className="flex justify-center gap-3 mb-6">\n        <button\n          onClick={() => setRunning((r) => !r)}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2"\n        >\n          {running ? "Pause" : "Demarrer"}\n        </button>\n        <button\n          onClick={applySettings}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Reinitialiser\n        </button>\n      </div>\n\n      <div className="bg-surface border border-border rounded-lg p-4">\n        <p className="text-xs text-muted mb-2">\n          Regle une duree pour un compte a rebours, ou laisse 0:00 pour un chronometre qui compte en avant.\n        </p>\n        <div className="flex items-center justify-center gap-2">\n          <input\n            type="number"\n            min={0}\n            value={inputMinutes}\n            onChange={(e) => setInputMinutes(Number(e.target.value))}\n            className="w-16 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm text-center"\n          />\n          <span className="text-muted text-sm">min</span>\n          <input\n            type="number"\n            min={0}\n            max={59}\n            value={inputSeconds}\n            onChange={(e) => setInputSeconds(Number(e.target.value))}\n            className="w-16 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm text-center"\n          />\n          <span className="text-muted text-sm">sec</span>\n          <button\n            onClick={applySettings}\n            className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5 text-sm"\n          >\n            Appliquer\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useNavigate, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport CampCircuitForm, { CampCircuitData } from "../components/CampCircuitForm";\nimport CircuitRunner from "../components/CircuitRunner";\nimport ReactionPicker, { ReactionSummary } from "../components/ReactionPicker";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface FeedItem {\n  targetType: "exercise" | "circuit";\n  targetId: string;\n  userId: string;\n  userName: string;\n  label: string;\n  date: string;\n  reactions: ReactionSummary[];\n}\n\ninterface CampExerciseData extends Program {\n  exercise: { id: string; name: string; unit: "REPS" | "SECONDS"; description: string | null };\n}\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  description: string | null;\n  code: string;\n  createdById: string;\n  startDate: string | null;\n  endDate: string | null;\n  exercises: CampExerciseData[];\n  circuits: CampCircuitData[];\n  members: { user: { id: string; name: string } }[];\n}\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n}\n\nconst RECURRENCE_LABEL: Record<string, (p: { recurrenceType: string; daysOfWeek: string | null; intervalDays: number | null }) => string> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n};\n\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const navigate = useNavigate();\n  const { user } = useAuth();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n  const [editingDescription, setEditingDescription] = useState(false);\n  const [descriptionDraft, setDescriptionDraft] = useState("");\n  const [savingDescription, setSavingDescription] = useState(false);\n  const [confirmingDelete, setConfirmingDelete] = useState(false);\n  const [deleting, setDeleting] = useState(false);\n  const [editingCircuitId, setEditingCircuitId] = useState<string | null>(null);\n  const [creatingCircuit, setCreatingCircuit] = useState(false);\n  const [runningCircuit, setRunningCircuit] = useState<CampCircuitData | null>(null);\n  const [runningExercise, setRunningExercise] = useState<CampExerciseData | null>(null);\n  const [feed, setFeed] = useState<FeedItem[] | null>(null);\n  const [duplicating, setDuplicating] = useState(false);\n\n  function loadFeed() {\n    if (!id) return;\n    api.get<FeedItem[]>(`/camps/${id}/feed`).then(setFeed);\n  }\n\n  async function duplicateCamp() {\n    if (!camp) return;\n    setDuplicating(true);\n    try {\n      const created = await api.post<{ id: string }>(`/camps/${camp.id}/duplicate`, {});\n      navigate(`/camps/${created.id}`);\n    } finally {\n      setDuplicating(false);\n    }\n  }\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n  }\n  useEffect(load, [id]);\n  useEffect(loadFeed, [id]);\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n  }, []);\n\n  async function deleteCamp() {\n    if (!camp) return;\n    setDeleting(true);\n    try {\n      await api.del(`/camps/${camp.id}`);\n      navigate("/camps");\n    } finally {\n      setDeleting(false);\n    }\n  }\n\n  async function saveDescription() {\n    if (!camp) return;\n    setSavingDescription(true);\n    try {\n      await api.put(`/camps/${camp.id}`, { description: descriptionDraft.trim() || null });\n      setEditingDescription(false);\n      load();\n    } finally {\n      setSavingDescription(false);\n    }\n  }\n\n  async function deleteCircuit(circuitId: string) {\n    await api.del(`/camp-circuits/${circuitId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(ce: CampExerciseData) {\n    await api.post("/logs", { campId: id, exerciseId: ce.exercise.id, setsDone: ce.targetSets, valueDone: ce.targetValue ?? 0 });\n    setRunningExercise(null);\n    load();\n  }\n\n  async function onCircuitChronoComplete(circuit: CampCircuitData, totalDurationSeconds: number) {\n    await api.post(`/camp-circuits/${circuit.id}/log`, { durationSeconds: totalDurationSeconds });\n    setRunningCircuit(null);\n    load();\n  }\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const isCoach = user?.id === camp.createdById;\n\n  if (runningExercise) {\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: runningExercise.exercise.name }]}\n          workSeconds={runningExercise.targetValue ?? 30}\n          restSeconds={0}\n          rounds={runningExercise.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(runningExercise)}\n          onCancel={() => setRunningExercise(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runningCircuit) {\n    const circuitItems = JSON.parse(runningCircuit.items) as { name: string }[];\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={circuitItems}\n          workSeconds={runningCircuit.workSeconds}\n          restSeconds={runningCircuit.restSeconds}\n          rounds={runningCircuit.rounds}\n          roundRestSeconds={runningCircuit.roundRestSeconds}\n          onComplete={(duration) => onCircuitChronoComplete(runningCircuit, duration)}\n          onCancel={() => setRunningCircuit(null)}\n        />\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent">{camp.code}</p>\n        </div>\n      </div>\n\n      <div className="flex items-center gap-4 flex-wrap mt-2">\n        <Link to={`/camps/${camp.id}/discussion`} className="text-sm text-accent hover:text-accentSoft">\n          💬 Discussion du camp\n        </Link>\n        <Link to={`/camps/${camp.id}/classement`} className="text-sm text-accent hover:text-accentSoft">\n          📊 Classement (regularite)\n        </Link>\n        <Link to={`/camps/${camp.id}/calendrier`} className="text-sm text-accent hover:text-accentSoft">\n          🗓️ Calendrier\n        </Link>\n        {isCoach && (\n          <>\n            <button onClick={duplicateCamp} disabled={duplicating} className="text-sm text-muted hover:text-accent">\n              {duplicating ? "Duplication..." : "Dupliquer le camp"}\n            </button>\n            <button onClick={() => setConfirmingDelete(true)} className="text-sm text-muted hover:text-accent ml-auto">\n              Supprimer le camp\n            </button>\n          </>\n        )}\n      </div>\n\n      {confirmingDelete && (\n        <div className="bg-surface border border-accent rounded-lg p-4 mt-3">\n          <p className="text-sm mb-3">\n            Supprimer definitivement le camp "{camp.name}" ? Cette action est irreversible : l\'historique des\n            seances de tous les membres pour ce camp sera perdu.\n          </p>\n          <div className="flex gap-2">\n            <button\n              onClick={deleteCamp}\n              disabled={deleting}\n              className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n            >\n              {deleting ? "Suppression..." : "Oui, supprimer"}\n            </button>\n            <button onClick={() => setConfirmingDelete(false)} className="text-muted hover:text-text text-sm px-2">\n              Annuler\n            </button>\n          </div>\n        </div>\n      )}\n\n      <div className="mt-4">\n        {editingDescription ? (\n          <div className="bg-surface2 border border-border rounded-lg p-3">\n            <textarea\n              value={descriptionDraft}\n              onChange={(e) => setDescriptionDraft(e.target.value)}\n              placeholder="Descriptif du camp..."\n              rows={3}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none mb-2"\n            />\n            <div className="flex gap-2">\n              <button\n                onClick={saveDescription}\n                disabled={savingDescription}\n                className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n              >\n                {savingDescription ? "Enregistrement..." : "Enregistrer"}\n              </button>\n              <button onClick={() => setEditingDescription(false)} className="text-muted hover:text-text text-sm px-2">\n                Annuler\n              </button>\n            </div>\n          </div>\n        ) : camp.description ? (\n          <div className="flex items-start justify-between gap-3">\n            <p className="text-sm text-muted italic">{camp.description}</p>\n            {isCoach && (\n              <button\n                onClick={() => {\n                  setDescriptionDraft(camp.description ?? "");\n                  setEditingDescription(true);\n                }}\n                className="text-xs text-accent hover:text-accentSoft shrink-0"\n              >\n                Modifier\n              </button>\n            )}\n          </div>\n        ) : (\n          isCoach && (\n            <button\n              onClick={() => {\n                setDescriptionDraft("");\n                setEditingDescription(true);\n              }}\n              className="text-xs text-accent hover:text-accentSoft"\n            >\n              + Ajouter un descriptif au camp\n            </button>\n          )\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Exercices du camp</h2>\n      <p className="text-muted text-sm mb-4">\n        {isCoach\n          ? "En tant que createur du camp, tu definis la consigne (objectif, frequence) suivie par tous les membres."\n          : "Consignes definies par le createur du camp."}\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map((ce) => {\n          const isEditing = editingExerciseId === ce.exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={ce.exercise.id}\n                campId={camp.id}\n                exerciseId={ce.exercise.id}\n                exerciseName={ce.exercise.name}\n                unit={ce.exercise.unit}\n                existing={ce}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          const unitLabel = ce.exercise.unit === "REPS" ? "reps" : "";\n          const valueLabel =\n            ce.exercise.unit === "SECONDS" && ce.targetValue != null\n              ? secondsToMMSS(ce.targetValue)\n              : `${ce.targetValue} ${unitLabel}`;\n          const canQuickChrono = ce.exercise.unit === "SECONDS" && ce.targetMode === "FIXED";\n\n          return (\n            <div key={ce.exercise.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">{ce.exercise.name}</p>\n                  <p className="text-sm text-muted">\n                    {ce.targetMode === "MAX"\n                      ? `${ce.targetSets} serie${ce.targetSets > 1 ? "s" : ""} a fond`\n                      : `${ce.targetSets} x ${valueLabel}`}{" "}\n                    · {RECURRENCE_LABEL[ce.recurrenceType](ce)}\n                  </p>\n                  {ce.description && <p className="text-xs text-muted mt-1 italic">"{ce.description}"</p>}\n                </div>\n                <div className="flex gap-3 items-center shrink-0">\n                  {canQuickChrono && (\n                    <button\n                      onClick={() => setRunningExercise(ce)}\n                      title="Lancer le chrono pour cet exercice"\n                      className="w-9 h-9 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                    >\n                      ⏱\n                    </button>\n                  )}\n                  <Link\n                    to={`/camps/${camp.id}/progression/${ce.exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                  {isCoach && (\n                    <button\n                      onClick={() => setEditingExerciseId(ce.exercise.id)}\n                      className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                    >\n                      Modifier\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n\n      <div className="flex items-center justify-between mt-8 mb-1">\n        <h2 className="font-display uppercase tracking-wide text-lg">Circuits training du camp</h2>\n        {isCoach && !creatingCircuit && (\n          <button onClick={() => setCreatingCircuit(true)} className="text-sm text-accent hover:text-accentSoft">\n            + Nouveau circuit\n          </button>\n        )}\n      </div>\n      <p className="text-muted text-sm mb-4">\n        Enchainements guides au chrono, alternative aux exercices individuels.\n      </p>\n\n      {creatingCircuit && (\n        <div className="mb-3">\n          <CampCircuitForm\n            campId={camp.id}\n            catalog={catalog}\n            onSaved={() => {\n              setCreatingCircuit(false);\n              load();\n            }}\n            onCancel={() => setCreatingCircuit(false)}\n          />\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {camp.circuits.map((circuit) => {\n          if (editingCircuitId === circuit.id) {\n            return (\n              <CampCircuitForm\n                key={circuit.id}\n                campId={camp.id}\n                catalog={catalog}\n                existing={circuit}\n                onSaved={() => {\n                  setEditingCircuitId(null);\n                  load();\n                }}\n                onCancel={() => setEditingCircuitId(null)}\n              />\n            );\n          }\n          const circuitItems = JSON.parse(circuit.items) as { name: string }[];\n          return (\n            <div key={circuit.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">🔁 {circuit.name}</p>\n                  <p className="text-sm text-muted">\n                    {circuitItems.map((i) => i.name).join(", ")} · {circuit.rounds} tour{circuit.rounds > 1 ? "s" : ""} ·{" "}\n                    {RECURRENCE_LABEL[circuit.recurrenceType](circuit)}\n                  </p>\n                  {circuit.description && <p className="text-xs text-muted mt-1 italic">"{circuit.description}"</p>}\n                </div>\n                <div className="flex gap-2 items-center shrink-0">\n                  <button\n                    onClick={() => setRunningCircuit(circuit)}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n                  >\n                    ⏱ Lancer\n                  </button>\n                  {isCoach && (\n                    <>\n                      <button\n                        onClick={() => setEditingCircuitId(circuit.id)}\n                        className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                      >\n                        Modifier\n                      </button>\n                      <button onClick={() => deleteCircuit(circuit.id)} className="text-muted hover:text-accent text-sm">\n                        Suppr.\n                      </button>\n                    </>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n        {camp.circuits.length === 0 && !creatingCircuit && (\n          <p className="text-muted text-sm italic">Aucun circuit pour l\'instant.</p>\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Fil d\'activite</h2>\n      <p className="text-muted text-sm mb-4">\n        Les dernieres seances validees par les membres du camp — pour s\'encourager, pas pour comparer.\n      </p>\n      <div className="space-y-2">\n        {feed === null && <p className="text-muted text-sm">Chargement...</p>}\n        {feed?.length === 0 && <p className="text-muted text-sm italic">Aucune activite pour l\'instant.</p>}\n        {feed?.map((item) => (\n          <div key={`${item.targetType}-${item.targetId}`} className="bg-surface border border-border rounded-lg p-3">\n            <p className="text-sm">\n              <span className="font-medium">{item.userName}</span> a valide{" "}\n              <span className="text-muted">{item.label}</span>\n            </p>\n            <div className="flex items-center justify-between mt-2">\n              <p className="text-[10px] text-muted">\n                {new Date(item.date).toLocaleDateString("fr-FR", { day: "2-digit", month: "short" })}\n              </p>\n              <ReactionPicker\n                targetType={item.targetType}\n                targetId={item.targetId}\n                reactions={item.reactions}\n                onChange={loadFeed}\n              />\n            </div>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampCalendar.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface CalendarDay {\n  date: string;\n  due: boolean;\n  done: boolean;\n  rest: boolean;\n}\n\nfunction monthLabel(monthStr: string): string {\n  const [y, m] = monthStr.split("-").map(Number);\n  return new Date(Date.UTC(y, m - 1, 1)).toLocaleDateString("fr-FR", { month: "long", year: "numeric" });\n}\n\nfunction shiftMonth(monthStr: string, delta: number): string {\n  const [y, m] = monthStr.split("-").map(Number);\n  const d = new Date(Date.UTC(y, m - 1 + delta, 1));\n  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;\n}\n\nexport default function CampCalendar() {\n  const { id: campId } = useParams<{ id: string }>();\n  const [month, setMonth] = useState(() => new Date().toISOString().slice(0, 7));\n  const [days, setDays] = useState<CalendarDay[] | null>(null);\n  const [campName, setCampName] = useState("");\n\n  useEffect(() => {\n    if (!campId) return;\n    api.get<{ name: string }>(`/camps/${campId}`).then((c) => setCampName(c.name));\n  }, [campId]);\n\n  useEffect(() => {\n    if (!campId) return;\n    setDays(null);\n    api.get<{ days: CalendarDay[] }>(`/camps/${campId}/calendar?month=${month}`).then((res) => setDays(res.days));\n  }, [campId, month]);\n\n  // Decalage pour que la grille commence un lundi (0=dimanche -> on veut lundi en premier)\n  const firstDay = days && days.length > 0 ? new Date(days[0].date) : null;\n  const leadingBlanks = firstDay ? (firstDay.getUTCDay() + 6) % 7 : 0;\n\n  return (\n    <div className="max-w-lg">\n      <Link to={`/camps/${campId}`} className="text-sm text-muted hover:text-accent">\n        ← Retour au camp\n      </Link>\n      <h1 className="font-display text-3xl uppercase tracking-wide mt-2 mb-4">Calendrier · {campName}</h1>\n\n      <div className="flex items-center justify-between mb-4">\n        <button onClick={() => setMonth((m) => shiftMonth(m, -1))} className="text-muted hover:text-accent px-2">\n          ← Precedent\n        </button>\n        <p className="font-display uppercase tracking-wide">{monthLabel(month)}</p>\n        <button onClick={() => setMonth((m) => shiftMonth(m, 1))} className="text-muted hover:text-accent px-2">\n          Suivant →\n        </button>\n      </div>\n\n      {days === null ? (\n        <p className="text-muted text-sm">Chargement...</p>\n      ) : (\n        <div className="bg-surface border border-border rounded-xl p-4">\n          <div className="grid grid-cols-7 gap-1 mb-2">\n            {["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"].map((d) => (\n              <p key={d} className="text-center text-[10px] text-muted uppercase">\n                {d}\n              </p>\n            ))}\n          </div>\n          <div className="grid grid-cols-7 gap-1">\n            {Array.from({ length: leadingBlanks }).map((_, i) => (\n              <div key={`blank-${i}`} />\n            ))}\n            {days.map((day) => {\n              const dayNum = Number(day.date.slice(8, 10));\n              let cellClass = "border-dashed border-border text-muted"; // pas prevu / futur\n              if (day.rest) cellClass = "bg-surface2 border-border text-muted";\n              else if (day.done) cellClass = "stamp-cell done";\n              else if (day.due) cellClass = "stamp-cell missed";\n              return (\n                <div\n                  key={day.date}\n                  title={day.date}\n                  className={`aspect-square rounded flex items-center justify-center text-xs border ${cellClass}`}\n                >\n                  {day.rest ? "😴" : dayNum}\n                </div>\n              );\n            })}\n          </div>\n          <div className="flex gap-4 mt-4 text-xs text-muted flex-wrap">\n            <span className="flex items-center gap-1">\n              <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell done" /> Fait\n            </span>\n            <span className="flex items-center gap-1">\n              <span className="w-2.5 h-2.5 rounded-sm inline-block stamp-cell missed" /> Manque\n            </span>\n            <span className="flex items-center gap-1">\n              <span className="w-2.5 h-2.5 rounded-sm inline-block bg-surface2 border border-border" /> Repos\n            </span>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/ActivityHistory.tsx'] = 'import { useEffect, useState } from "react";\nimport { api, downloadFile } from "../api/client";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface Stats {\n  totalSessions: number;\n  totalPracticeSeconds: number;\n  exerciseCount: number;\n  personalBests: { exerciseName: string; unit: string; best: number }[];\n}\n\ntype ActivityItem =\n  | { type: "exercise"; date: string; exerciseName: string; unit: "REPS" | "SECONDS"; campName: string; setsDone: number; valueDone: number }\n  | { type: "circuit"; date: string; circuitName: string; campName: string; durationSeconds: number }\n  | { type: "chrono"; date: string; name: string | null; items: string[]; totalDurationSeconds: number; rounds: number };\n\nfunction formatDuration(totalSeconds: number): string {\n  const h = Math.floor(totalSeconds / 3600);\n  const m = Math.round((totalSeconds % 3600) / 60);\n  if (h === 0) return `${m} min`;\n  return `${h} h ${m.toString().padStart(2, "0")}`;\n}\n\nexport default function ActivityHistory() {\n  const [stats, setStats] = useState<Stats | null>(null);\n  const [items, setItems] = useState<ActivityItem[] | null>(null);\n  const [exporting, setExporting] = useState(false);\n\n  useEffect(() => {\n    api.get<{ stats: Stats; items: ActivityItem[] }>("/activity").then((res) => {\n      setStats(res.stats);\n      setItems(res.items);\n    });\n  }, []);\n\n  async function onExport() {\n    setExporting(true);\n    try {\n      await downloadFile("/activity/export.csv", "goteam-historique.csv");\n    } finally {\n      setExporting(false);\n    }\n  }\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-1">\n        <h1 className="font-display text-3xl uppercase tracking-wide">Mon historique</h1>\n        <button\n          onClick={onExport}\n          disabled={exporting}\n          className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5 disabled:opacity-60"\n        >\n          {exporting ? "Export..." : "⬇ Exporter en CSV"}\n        </button>\n      </div>\n      <p className="text-muted text-sm mb-6">Toutes tes seances, tous camps et circuits confondus.</p>\n\n      {stats && (\n        <div className="grid grid-cols-3 gap-3 mb-6">\n          <div className="bg-surface border border-border rounded-xl p-4 text-center">\n            <p className="font-display text-2xl text-accent">{stats.totalSessions}</p>\n            <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Seances au total</p>\n          </div>\n          <div className="bg-surface border border-border rounded-xl p-4 text-center">\n            <p className="font-display text-2xl text-accent">{formatDuration(stats.totalPracticeSeconds)}</p>\n            <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Temps de pratique</p>\n          </div>\n          <div className="bg-surface border border-border rounded-xl p-4 text-center">\n            <p className="font-display text-2xl text-accent">{stats.exerciseCount}</p>\n            <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Exercices differents</p>\n          </div>\n        </div>\n      )}\n\n      {stats && stats.personalBests.length > 0 && (\n        <div className="bg-surface border border-border rounded-xl p-4 mb-6">\n          <h2 className="font-display uppercase tracking-wide text-sm mb-3">Records personnels (sur une serie)</h2>\n          <div className="grid sm:grid-cols-2 gap-2">\n            {stats.personalBests.map((pb) => (\n              <div key={pb.exerciseName} className="flex items-center justify-between text-sm">\n                <span className="text-muted">{pb.exerciseName}</span>\n                <span className="font-mono text-accent">\n                  {pb.unit === "SECONDS" ? secondsToMMSS(pb.best) : `${pb.best} reps`}\n                </span>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n\n      <h2 className="font-display uppercase tracking-wide text-sm mb-3">Journal des seances</h2>\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n      {items?.length === 0 && <p className="text-muted text-sm">Aucune seance enregistree pour l\'instant.</p>}\n\n      <div className="space-y-2">\n        {items?.map((item, index) => (\n          <div key={index} className="bg-surface border border-border rounded-lg p-3 flex items-center justify-between gap-3">\n            <div>\n              {item.type === "exercise" && (\n                <>\n                  <p className="text-sm font-medium">{item.exerciseName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · {item.setsDone} x{" "}\n                    {item.unit === "SECONDS" ? secondsToMMSS(item.valueDone) : `${item.valueDone} reps`}\n                  </p>\n                </>\n              )}\n              {item.type === "circuit" && (\n                <>\n                  <p className="text-sm font-medium">🔁 {item.circuitName}</p>\n                  <p className="text-xs text-muted">\n                    {item.campName} · {formatDuration(item.durationSeconds)}\n                  </p>\n                </>\n              )}\n              {item.type === "chrono" && (\n                <>\n                  <p className="text-sm font-medium">⏱ {item.name || "Circuit libre"}</p>\n                  <p className="text-xs text-muted">\n                    {item.items.join(", ")} · {item.rounds} tour{item.rounds > 1 ? "s" : ""} ·{" "}\n                    {formatDuration(item.totalDurationSeconds)}\n                  </p>\n                </>\n              )}\n            </div>\n            <p className="text-xs text-muted shrink-0">\n              {new Date(item.date).toLocaleDateString("fr-FR", { day: "2-digit", month: "short" })}\n            </p>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Login.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, Navigate, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { ApiError } from "../api/client";\n\nexport default function Login() {\n  const { login, user } = useAuth();\n  const navigate = useNavigate();\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  if (user) return <Navigate to="/aujourdhui" replace />;\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      await login(email, password);\n      navigate("/aujourdhui");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Connexion impossible, reessaie.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Connexion</h1>\n          <p className="text-muted text-sm mb-6">Reprends ton entrainement la ou tu l\'as laisse.</p>\n\n          <form onSubmit={onSubmit} className="space-y-4">\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="email">\n                Email\n              </label>\n              <input\n                id="email"\n                type="email"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <div className="flex items-center justify-between mb-1">\n                <label className="block text-sm text-muted" htmlFor="password">\n                  Mot de passe\n                </label>\n                <Link to="/mot-de-passe-oublie" className="text-xs text-accent hover:text-accentSoft">\n                  Oublie ?\n                </Link>\n              </div>\n              <input\n                id="password"\n                type="password"\n                required\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n\n            {error && <p className="text-sm text-accent">{error}</p>}\n\n            <button\n              type="submit"\n              disabled={busy}\n              className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n            >\n              {busy ? "Connexion..." : "Se connecter"}\n            </button>\n          </form>\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          Pas encore de compte ?{" "}\n          <Link to="/inscription" className="text-accent hover:text-accentSoft">\n            Cree-en un\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/ForgotPassword.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\n\nexport default function ForgotPassword() {\n  const [email, setEmail] = useState("");\n  const [message, setMessage] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setMessage(null);\n    setBusy(true);\n    try {\n      const res = await api.post<{ message: string }>("/auth/forgot-password", { email });\n      setMessage(res.message);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Une erreur est survenue.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Mot de passe oublie</h1>\n          <p className="text-muted text-sm mb-6">\n            Entre ton email, on t\'envoie un lien pour choisir un nouveau mot de passe.\n          </p>\n\n          {message ? (\n            <p className="text-sm text-success">{message}</p>\n          ) : (\n            <form onSubmit={onSubmit} className="space-y-4">\n              <div>\n                <label className="block text-sm text-muted mb-1" htmlFor="email">\n                  Email\n                </label>\n                <input\n                  id="email"\n                  type="email"\n                  required\n                  value={email}\n                  onChange={(e) => setEmail(e.target.value)}\n                  className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n                />\n              </div>\n\n              {error && <p className="text-sm text-accent">{error}</p>}\n\n              <button\n                type="submit"\n                disabled={busy}\n                className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n              >\n                {busy ? "Envoi..." : "Envoyer le lien"}\n              </button>\n            </form>\n          )}\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          <Link to="/connexion" className="text-accent hover:text-accentSoft">\n            Retour a la connexion\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/ResetPassword.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, useNavigate, useSearchParams } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\n\nexport default function ResetPassword() {\n  const [searchParams] = useSearchParams();\n  const navigate = useNavigate();\n  const token = searchParams.get("token") ?? "";\n  const [newPassword, setNewPassword] = useState("");\n  const [message, setMessage] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setMessage(null);\n    setBusy(true);\n    try {\n      const res = await api.post<{ message: string }>("/auth/reset-password", { token, newPassword });\n      setMessage(res.message);\n      setTimeout(() => navigate("/connexion"), 2000);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de reinitialiser le mot de passe.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Nouveau mot de passe</h1>\n\n          {!token ? (\n            <p className="text-sm text-accent">\n              Lien invalide. Redemande un lien de reinitialisation depuis la page de connexion.\n            </p>\n          ) : message ? (\n            <p className="text-sm text-success">{message} Redirection...</p>\n          ) : (\n            <form onSubmit={onSubmit} className="space-y-4">\n              <div>\n                <label className="block text-sm text-muted mb-1" htmlFor="newPassword">\n                  Nouveau mot de passe\n                </label>\n                <input\n                  id="newPassword"\n                  type="password"\n                  required\n                  minLength={8}\n                  value={newPassword}\n                  onChange={(e) => setNewPassword(e.target.value)}\n                  className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n                />\n                <p className="text-xs text-muted mt-1">8 caracteres minimum.</p>\n              </div>\n\n              {error && <p className="text-sm text-accent">{error}</p>}\n\n              <button\n                type="submit"\n                disabled={busy}\n                className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n              >\n                {busy ? "Enregistrement..." : "Changer le mot de passe"}\n              </button>\n            </form>\n          )}\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          <Link to="/connexion" className="text-accent hover:text-accentSoft">\n            Retour a la connexion\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/ReactionPicker.tsx'] = 'import { useState } from "react";\nimport { api } from "../api/client";\n\nconst REACTIONS = [\n  { key: "OVATION", label: "Ovation", emoji: "🙌" },\n  { key: "RESPECT", label: "Respect", emoji: "🫡" },\n  { key: "HAKA", label: "Haka", emoji: "💥" },\n  { key: "OLA", label: "Ola", emoji: "🌊" },\n  { key: "HYMNE", label: "Hymne", emoji: "🎶" },\n  { key: "CLAPPING", label: "Clapping", emoji: "👏" },\n  { key: "TIFO", label: "Tifo", emoji: "🎨" },\n  { key: "TAMBOURINAGE", label: "Tambourinage", emoji: "🥁" },\n];\n\nexport interface ReactionSummary {\n  type: string;\n  count: number;\n  reactedByMe: boolean;\n}\n\ninterface Props {\n  targetType: "exercise" | "circuit";\n  targetId: string;\n  reactions: ReactionSummary[];\n  onChange: () => void;\n}\n\nexport default function ReactionPicker({ targetType, targetId, reactions, onChange }: Props) {\n  const [open, setOpen] = useState(false);\n\n  async function toggle(type: string) {\n    setOpen(false);\n    await api.post("/reactions", { targetType, targetId, type });\n    onChange();\n  }\n\n  return (\n    <div className="relative inline-block">\n      <div className="flex items-center gap-1 flex-wrap">\n        {reactions.map((r) => {\n          const def = REACTIONS.find((d) => d.key === r.type);\n          if (!def) return null;\n          return (\n            <button\n              key={r.type}\n              onClick={() => toggle(r.type)}\n              title={def.label}\n              className={`text-xs rounded-full px-2 py-0.5 border ${\n                r.reactedByMe ? "bg-accent/20 border-accent" : "bg-surface2 border-border"\n              }`}\n            >\n              {def.emoji} {r.count}\n            </button>\n          );\n        })}\n        <button\n          onClick={() => setOpen((o) => !o)}\n          className="text-xs rounded-full px-2 py-0.5 border border-dashed border-border text-muted hover:text-accent"\n        >\n          + reagir\n        </button>\n      </div>\n\n      {open && (\n        <div className="absolute z-10 mt-1 bg-surface border border-border rounded-lg p-2 grid grid-cols-4 gap-1 shadow-lg">\n          {REACTIONS.map((r) => (\n            <button\n              key={r.key}\n              onClick={() => toggle(r.key)}\n              title={r.label}\n              className="text-xl hover:bg-surface2 rounded p-1"\n            >\n              {r.emoji}\n            </button>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/App.tsx'] = 'import { Navigate, Route, Routes } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "./context/AuthContext";\nimport Layout from "./components/Layout";\n\nimport Login from "./pages/Login";\nimport Register from "./pages/Register";\nimport Profile from "./pages/Profile";\nimport Dashboard from "./pages/Dashboard";\nimport CreateCamp from "./pages/CreateCamp";\nimport JoinCamp from "./pages/JoinCamp";\nimport CampDetail from "./pages/CampDetail";\nimport Today from "./pages/Today";\nimport Progress from "./pages/Progress";\nimport ExerciseRepository from "./pages/ExerciseRepository";\nimport CampChat from "./pages/CampChat";\nimport Messages from "./pages/Messages";\nimport CampLeaderboard from "./pages/CampLeaderboard";\nimport Chrono from "./pages/Chrono";\nimport ActivityHistory from "./pages/ActivityHistory";\nimport CampCalendar from "./pages/CampCalendar";\nimport ForgotPassword from "./pages/ForgotPassword";\nimport ResetPassword from "./pages/ResetPassword";\n\nfunction Private({ children }: { children: ReactNode }) {\n  const { user, loading } = useAuth();\n  if (loading) return <div className="min-h-screen flex items-center justify-center text-muted">Chargement...</div>;\n  if (!user) return <Navigate to="/connexion" replace />;\n  return <Layout>{children}</Layout>;\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path="/connexion" element={<Login />} />\n      <Route path="/inscription" element={<Register />} />\n      <Route path="/mot-de-passe-oublie" element={<ForgotPassword />} />\n      <Route path="/reinitialiser-mot-de-passe" element={<ResetPassword />} />\n\n      <Route path="/aujourdhui" element={<Private><Today /></Private>} />\n      <Route path="/profil" element={<Private><Profile /></Private>} />\n      <Route path="/camps" element={<Private><Dashboard /></Private>} />\n      <Route path="/camps/creer" element={<Private><CreateCamp /></Private>} />\n      <Route path="/camps/rejoindre" element={<Private><JoinCamp /></Private>} />\n      <Route path="/camps/:id" element={<Private><CampDetail /></Private>} />\n      <Route path="/camps/:id/progression/:exerciseId" element={<Private><Progress /></Private>} />\n      <Route path="/camps/:id/calendrier" element={<Private><CampCalendar /></Private>} />\n      <Route path="/exercices" element={<Private><ExerciseRepository /></Private>} />\n      <Route path="/camps/:id/discussion" element={<Private><CampChat /></Private>} />\n      <Route path="/camps/:id/classement" element={<Private><CampLeaderboard /></Private>} />\n      <Route path="/chrono" element={<Private><Chrono /></Private>} />\n      <Route path="/historique" element={<Private><ActivityHistory /></Private>} />\n      <Route path="/messages" element={<Private><Messages /></Private>} />\n\n      <Route path="*" element={<Navigate to="/aujourdhui" replace />} />\n    </Routes>\n  );\n}\n'

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

